function tunnelNodeParentDug(node) {
  if (node.parent === "wall") return tunnelWallBroken;
  const parent = TUNNEL_NODES.find(n => n.id === node.parent);
  return parent ? parent.dug : false;
}

function tunnelNodeParentPos(node) {
  if (node.parent === "wall") return { x: TUNNELTOWN_WALL_X + 16, h: 0 };
  const parent = TUNNEL_NODES.find(n => n.id === node.parent);
  return parent ? { x: parent.x, h: parent.heightAboveGround } : null;
}

// any two dug nodes that land at nearly the same height read as one
// physical shelf, whether or not they're actually parent/child -- e.g.
// s5/s5r sit at the same height by design, so their little ledges
// should merge into a single wide one rather than draw as two
// separate, uselessly-stacked planks.
// Used by both the physics floor and the ledge render so they always
// agree on where the walkable span actually is.
// Was 10. Every INTENDED merge in TUNNEL_NODES sits at the exact same
// heightAboveGround (diff 0) -- s3b/s4/s5 all h90, s5u2/s5uTurn/s5uSide
// all h250, u3/u3Turn both h300, etc. 10 was loose enough to also merge
// totally unrelated branches that just happen to land 10 units apart:
// s1u1 (a dead-end climb spur off s1, h80) sits only 10 below the main
// s3b/s4/s5 corridor (h90) and within the 100px x-tolerance of s3b
// (dx60) -- verified via a scripted grid probe that once BOTH sides are
// dug, tunnelMergedLedgeSpan(s5) returns one 268-unit-wide span
// (x936-1204) at the LOWER merged height (80, since the merge height is
// the min of the group), dragging the entire real height-90 corridor's
// landing platform down to 80. Standing at your own actual height-90
// ledge no longer registers as "on the platform" (playerBottom=90 fails
// the <=platformTop check against platformTop=80) -- you fall straight
// through solid-looking dirt, and the phantom span reaches left all the
// way to s1u1's own dead end, well past anything actually dug over
// there. Real repro of "packed dirt to my left falls through once I dig
// the hole above me." 4 keeps every same-height intended merge (diff 0)
// working while no longer bridging two branches that only coincidentally
// land close but not equal.
const TUNNEL_LEDGE_MERGE_TOLERANCE = 4;
// height tolerance alone isn't enough to decide two nodes belong to the
// same shelf -- several completely unrelated branches happen to land on
// the same round heightAboveGround (e.g. u1 at 80 and s1u1 at 80, ~160
// world units apart on opposite sides of the map). Without also checking
// x-distance, those got merged into one "ledge" spanning the whole gap
// between them -- a plank rendered floating across a stretch of solid,
// never-dug dirt, which is exactly what reads as a hole/platform whose
// placement "makes zero sense." Real same-shelf merges (the sequential
// s5 corridor nodes, etc.) were assumed to all be within ~80 units of
// each other, so 100 seemed to comfortably cover intended merges while
// excluding cross-branch coincidences.
// Was 100 -- s5 (x1180) and its own "side" (plain-walk, not a jump)
// child s5r used to sit at x1290 (110 apart), which a real physics
// simulation later confirmed was actually just too far to reach by
// walking/falling at all -- fixed at the source by pulling s5r's whole
// subtree back in to a real dx of 80 (see s5r's own comment), not by
// widening this tolerance further. 130 stays as a small buffer over the
// intended ~80-ish same-shelf spacing used throughout this corridor,
// while every unrelated same-height-but-different-branch pair on the
// map still sits 160+ apart, well clear of it.
const TUNNEL_LEDGE_MERGE_X_TOLERANCE = 130;
// also returns a single unified `height` for the whole merged group (the
// lowest of the bunch) -- each node used to draw/collide at its OWN
// heightAboveGround even after their spans merged, which could still
// read as separate stacked planks a few px apart vertically instead of
// the single shelf the span-merge intended.
// a shelfGap hole (see s5uHole) sits deliberately at the EXACT same x/
// height as the small standalone spur it's carved out of (s5uSide), not
// offset to one side of it -- unlike a trapdoor sitting at the edge of
// its own small merge group (uTopDrop, s5u5Drop), the normal single-
// sided left/right clip in tunnelMergedLedgeSpan can't represent "the
// gap is centered on and exactly as wide as this whole spur": clipping
// both directions in from a dead-center gap just inverts left/right
// into a nonsense negative-width span (verified: broke landing across
// the ENTIRE merged s5uSide/s5uTurn/s5u2 shelf, not just the small area
// over the hole). Simplest correct fix: once a node's own footprint has
// literally been replaced by a dug shelfGap child sitting right on top
// of it, drop that node out of every merge/landing check entirely,
// rather than trying to carve a partial gap out of it.
function tunnelNodeHollowedOut(node) {
  return TUNNEL_NODES.some(other => other.shelfGap && other.dug && other.parent === node.id &&
    Math.abs(other.x - node.x) <= 24 &&
    Math.abs(other.heightAboveGround - node.heightAboveGround) <= TUNNEL_LEDGE_MERGE_TOLERANCE);
}

function tunnelMergedLedgeSpan(node) {
  // flood-fill the WHOLE connected shelf, not just nodes directly within
  // tolerance of this one node -- a straight corridor of 4+ dug nodes
  // each ~60-90 units apart (well under the 100 x-tolerance) can still
  // stretch further than 100 end-to-end, so the old direct-neighbors-only
  // check gave different nodes in that same corridor DIFFERENT groups
  // (and different merged heights) depending on which one you started
  // from -- e.g. s1u1 merged with s3b alone (height 80), while s3b also
  // separately merged with s4/s5 (height 90). Two overlapping spans a
  // few px apart in height, rendered/landed-on as two stacked planks
  // instead of the one continuous shelf they're actually meant to be.
  // Flood-filling transitively (still gated by the same pairwise
  // tolerances at each hop) means every node in one real corridor agrees
  // on the exact same left/right/height, however long the chain --
  // while unrelated nodes that just happen to share a height far apart
  // (no hop-by-hop path within tolerance) still never merge.
  const group = [node];
  const inGroup = new Set([node]);
  for (let i = 0; i < group.length; i++) {
    const cur = group[i];
    TUNNEL_NODES.forEach(other => {
      if (inGroup.has(other) || !other.dug || other.heightAboveGround <= 0 || other.trapGap || other.shelfGap || tunnelNodeHollowedOut(other)) return;
      if (Math.abs(other.heightAboveGround - cur.heightAboveGround) <= TUNNEL_LEDGE_MERGE_TOLERANCE &&
          Math.abs(other.x - cur.x) <= TUNNEL_LEDGE_MERGE_X_TOLERANCE) {
        inGroup.add(other);
        group.push(other);
      }
    });
  }
  let left = node.x - 24, right = node.x + 24, height = node.heightAboveGround;
  group.forEach(other => {
    left = Math.min(left, other.x - 24);
    right = Math.max(right, other.x + 24);
    height = Math.min(height, other.heightAboveGround);
  });
  // a dug trapdoor punches a real gap in what would otherwise be one
  // continuous shelf -- without this, this node's own span still bridges
  // straight across it (each node computes its span independently), so
  // the floor would silently re-appear under the "broken" plank instead
  // of actually dropping the player through it. Clip to whichever gap is
  // closest on either side of THIS node's own position.
  // NOT gated on the trap already being inside the current left/right --
  // a neighboring node one hop further down the chain (like s4, merged
  // with s5 but not directly with the trap itself) can independently
  // reach to within a few px of the gap without ever containing the
  // trap's exact x, and this must still clip that overlap away. Math.min/
  // max alone are safe here: they only ever pull left/right IN toward the
  // gap, never push them back out past where they already were.
  TUNNEL_NODES.forEach(other => {
    // shelfGap behaves exactly like trapGap for this clip -- a dug hole
    // punches a real gap in whatever shelf it's part of, whether or not
    // it also drops you all the way to true ground (trapGap) or just
    // onto a real ledge one short hop below (shelfGap, see s5uHole).
    if (!(other.trapGap || other.shelfGap) || !other.dug) return;
    // height-gated the same way the merge above is -- a trapdoor only
    // punches a gap in a shelf it's actually PART OF. Without this, a
    // trapdoor was clipping any span that happened to pass near its x
    // at ANY height, including elevated walkways far above/below it
    // that have nothing to do with it -- e.g. s5trap (height 90)
    // truncating the merged shelf between s5u2/s5uTurn up at height
    // 250, carving an unintended gap in a walkway 160 units above it
    // where no plank ever got drawn.
    // gated against the GROUP's merged height now (not just this node's
    // own), since the flood-fill above can pull `height` down to a
    // different node's height than this one's own
    if (Math.abs(other.heightAboveGround - height) > TUNNEL_LEDGE_MERGE_TOLERANCE) return;
    if (other.x > node.x) right = Math.min(right, other.x - 20);
    if (other.x < node.x) left = Math.max(left, other.x + 20);
  });
  return { left, right, height };
}

// how far you can physically WALK -- right up to the edge of any
// currently-reachable node (its own parent already dug), whether or
// not that node itself has been dug yet, so you can always reach the
// next spot to dig it. Deliberately tight (not a wide flood-lit
// stretch) -- separate from the visual carve shapes below.
//
// Real repro (falling off the dead end at s5r2, x1210): height-only
// matching let a totally unrelated frontier node clear across the map
// (s1u1, x810, just a coincidentally similar height) win the Math.max
// the instant the fall drifted a few px past s5r2's own tight margin --
// snapping the player 400+ units backward mid-fall, since this coarse
// boundary has no idea those two nodes have nothing to do with each
// other. Now also requires the node to be within a generous x range of
// the player's OWN current position (not just of each other, the way
// tunnelMergedLedgeSpan's tolerance works) -- big enough to cover any
// real jump/fall drift, nowhere near big enough to reach clear across
// the map to a different branch entirely.
function tunnelWalkLimit(playerH, playerX) {
  if (!tunnelWallBroken) return TUNNELTOWN_WALL_X - 6;
  // base fallback is the player's OWN current x (a no-op limit), not a
  // fixed constant near the entrance -- near a dead end's own edge
  // (e.g. mid-fall off s5r2), it's normal for NOTHING to qualify within
  // xRange once the player's height has drifted past every nearby
  // node's own height band. Falling back to a fixed low constant then
  // yanked the player call the way back to the tunnel entrance, which
  // is a far worse teleport than just... not clamping anything that
  // frame. Combined with the caller's own tunnelPositionRevealed guard,
  // this keeps the clamp a pure backstop instead of an active hazard.
  let limit = playerX != null ? playerX : TUNNELTOWN_WALL_X + 40;
  // was pure x, with no regard for height at all -- meaning a node dug
  // way up in the air (like the far end of the raised reward path) pushed
  // this boundary out just as far at GROUND level too, letting you just
  // walk the floor straight past where any ground-level path actually
  // exists, underneath a tunnel that's really only open up in the air.
  // Only nodes reasonably close to the player's own current height now
  // count toward the limit -- matches the same margin the real 2D
  // dig-collision uses (tunnelHoleContains), so this coarse backup
  // stays consistent with it.
  const ry = TUNNEL_PASSAGE_HEIGHT / 2 + 8;
  const xRange = 260;
  TUNNEL_NODES.forEach(node => {
    if (playerX != null && Math.abs(node.x - playerX) > xRange) return;
    if (tunnelNodeParentDug(node) && Math.abs(node.heightAboveGround - (playerH || 0)) <= ry) {
      limit = Math.max(limit, node.x + 30);
    }
  });
  return limit;
}

// true if the point (x, heightAboveGround) falls inside a single dug
// "hole" ellipse centered at (cx, ch) -- a little more forgiving than
// the render ellipse (see addTunnelHoleToPath below) so ordinary
// walking/jumping through a real passage never feels clipped
function tunnelHoleContains(cx, ch, x, h) {
  // margins wider than the render ellipse (rx24, ry~50 -- see
  // addTunnelHoleToPath) so ordinary walking to the edge of a dug
  // passage never feels clipped or freezes at the coarse-vs-fine
  // boundary gap. Used to be MUCH wider (rx40, ry+20) -- in a tightly
  // packed cluster like the up-chain (9 nodes inside a ~150x300 box),
  // that many overlapping oversized ellipses unioned into one big blob
  // of walkable "revealed" space well beyond what any tube actually
  // draws, letting the player stand in open air with no visible tunnel
  // under them at all. Trimmed back to a smaller, still-comfortable
  // buffer over the render size.
  const rx = 28, ry = TUNNEL_PASSAGE_HEIGHT / 2 + 8;
  const dx = (x - cx) / rx, dh = (h - ch) / ry;
  return dx * dx + dh * dh <= 1;
}

// the real 2D dig-collision check -- true if this exact point is inside
// the always-open nook, the broken wall's own opening, or the tube+hole
// chain leading to (and including) any node whose parent has already
// been dug. Mirrors exactly what drawTunnelTownScene's clip actually
// reveals, so solid-looking dirt is always solid in every direction,
// not just blocked by a single rightward x-limit.
function tunnelPositionRevealed(x, h) {
  // the permanent dirt core is solid no matter what -- checked FIRST, so
  // it overrides any tube/hole that happens to reach into the same area.
  // Without this it was purely decorative: it drew on top of already-open
  // space but never actually blocked movement, so you could just walk
  // straight through what looked like solid ground.
  if (tunnelCoreMoundContains(x, h)) return false;
  if (x < TUNNELTOWN_WALL_X + 6) return true; // the always-open starting nook
  if (!tunnelWallBroken) return false;
  if (tunnelHoleContains(TUNNELTOWN_WALL_X + 16, 0, x, h)) return true;
  // a merged ledge (see tunnelMergedLedgeSpan) can walk a good deal wider
  // than the narrow parent-child tube that originally dug it -- ledges
  // merge across up to TUNNEL_LEDGE_MERGE_X_TOLERANCE (100px), well past
  // a tube's own rx (28px) reveal band. Without this, walking along a
  // wide shelf eventually steps past the tube's reveal band while still
  // standing on solid, already-dug floor, and the snap-back-to-safe-spot
  // logic freezes the player in place every frame -- reads exactly like
  // the core-mound softlock but has nothing to do with the mound.
  // margin matches the physics ledge-landing check's own AABB tolerance --
  // that check compares the player's full body rect (x .. x+width) against
  // [left,right], but here we're given the player's CENTER (x = centerX),
  // so the equivalent slack is only half the player's width, not the full
  // width -- using the full width here would under-cover, not over-cover.
  // +2 used to be razor-exact against the player's own per-frame move
  // step (3px): walking off the very end of a shelf could land the
  // recovery check's rejected x and its retried x on the SAME losing
  // side of this boundary every single frame (real repro: center x=603
  // vs a left-margin edge at 604, forever), which reads as the player
  // getting stuck floating/glitching in place, unable to walk any
  // further even though nothing should be blocking them. A few extra px
  // of buffer (covering more than one full move-step) means a frame
  // that fails the check is never immediately followed by a retry that
  // fails at the exact same spot.
  const tunnelLedgeRevealMargin = player.width / 2 + 8;
  for (const node of TUNNEL_NODES) {
    if (!node.dug || node.heightAboveGround <= 0 || node.trapGap || node.shelfGap || tunnelNodeHollowedOut(node)) continue;
    const { left, right, height: platformTop } = tunnelMergedLedgeSpan(node);
    // dropping the lower bound all the way to 0 fixed the true left-edge
    // softlock (walking off the very END of a dead-end ledge with nothing
    // dug further out), but doing it across the ENTIRE span was too much
    // once ledges started merging transitively into much longer shelves
    // (see tunnelMergedLedgeSpan) -- a single merged corridor 400+ units
    // wide meant the WHOLE rectangle underneath it, ground to ceiling,
    // read as "revealed" no matter where in that width you were, not
    // just near its two actual edges. That's a giant walk-through-solid-
    // dirt cavity, not a fix. A fall only ever happens at (roughly) the
    // player's own x, right where they walked off -- so the extended
    // lower bound only needs to cover a narrow band near the span's own
    // left/right edges, not its whole interior width.
    // ALSO gated on the player still actively falling (vy < 0) -- without
    // this, the same relaxed-to-0 band stayed "revealed" forever, even
    // once the player had already landed and come to rest down at true
    // ground level (vy settles to 0 the instant the universal y<=0 floor
    // catch fires, elsewhere in applyPhysics, earlier in the same frame).
    // That let you stand indefinitely on ordinary undug dirt near the
    // edge of ANY elevated dug ledge, anywhere on the map -- reported as
    // landing on "hardened dirt" that clearly hadn't been dug. Falling
    // PAST the edge still needs the wide-open band (vy stays < 0 the
    // whole way down), so the original dead-end softlock this was built
    // to fix is untouched -- only resting there afterward is now blocked.
    const nearSpanEdge = x <= left + tunnelLedgeRevealMargin || x >= right - tunnelLedgeRevealMargin;
    const lowerBound = (nearSpanEdge && player.vy < 0) ? 0 : platformTop - 6;
    if (x >= left - tunnelLedgeRevealMargin && x <= right + tunnelLedgeRevealMargin &&
        h >= lowerBound && h <= platformTop + TUNNEL_PASSAGE_HEIGHT / 2 + 8) {
      return true;
    }
  }
  for (const node of TUNNEL_NODES) {
    if (!tunnelNodeParentDug(node)) continue; // frontier not reached yet
    const parentPos = tunnelNodeParentPos(node);
    if (parentPos) {
      const dist = Math.abs(parentPos.x - node.x) + Math.abs(parentPos.h - node.heightAboveGround);
      const steps = Math.max(1, Math.round(dist / 16));
      for (let i = 0; i <= steps; i++) {
        const t = i / steps;
        const tx = parentPos.x + (node.x - parentPos.x) * t;
        const th = parentPos.h + (node.heightAboveGround - parentPos.h) * t;
        if (tunnelHoleContains(tx, th, x, h)) return true;
      }
    }
    if (tunnelHoleContains(node.x, node.heightAboveGround, x, h)) return true;
  }
  return false;
}

// adds one small oval "opening" to the current path, in screen space --
// person-sized, not a big room reveal
function addTunnelHoleToPath(camX, x, h) {
  const sx = x - camX, sy = gy + cameraY - h;
  const rx = 24, ry = TUNNEL_PASSAGE_HEIGHT / 2 + 6;
  ctx.moveTo(sx + rx, sy);
  ctx.ellipse(sx, sy, rx, ry, 0, 0, Math.PI * 2);
}

// a narrow tube of overlapping ovals connecting two dug points -- the
// actual walkable corridor between them, not a flood-filled rectangle
function addTunnelTubeToPath(camX, x1, h1, x2, h2) {
  const dist = Math.abs(x1 - x2) + Math.abs(h1 - h2);
  const steps = Math.max(1, Math.round(dist / 16));
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    addTunnelHoleToPath(camX, x1 + (x2 - x1) * t, h1 + (h2 - h1) * t);
  }
}

// shared "diggable patch of earth" marker -- a soft radial glow (rather
// than one flat translucent tint), a darker rim so it reads as an
// actual depression in the dirt, and a few thin root-hair cracks
// radiating out so it doesn't look like a plain blob. Used for every
// undug spot in the scene (the wall's own soft spot included) so the
// player learns one consistent visual language for "diggable here".
// builds an irregular ellipse-ish outline -- same overall size as a true
// ellipse but with each point nudged in/out along its own radius, so the
// shape reads as an actual ragged hole torn in dirt rather than a clean
// geometric oval "pasted on" over the texture underneath
function irregularOvalPoints(cx, cy, rx, ry, seed, jitter, count) {
  const pts = [];
  for (let i = 0; i < count; i++) {
    const a = (i / count) * Math.PI * 2;
    const wobble = 1 + (pseudoRandom(seed + i * 7.3) - 0.5) * jitter;
    pts.push({ x: cx + Math.cos(a) * rx * wobble, y: cy + Math.sin(a) * ry * wobble });
  }
  return pts;
}

function pathFromPoints(pts) {
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i <= pts.length; i++) {
    const p = pts[i % pts.length];
    const prev = pts[(i - 1) % pts.length];
    ctx.quadraticCurveTo(prev.x, prev.y, (prev.x + p.x) / 2, (prev.y + p.y) / 2);
  }
  ctx.closePath();
}

function drawDigSoftSpot(cx, cy, rx, ry, seed) {
  // a solid clump of dirt behind the marker itself, noticeably bigger
  // than the marker -- without this, any marker sitting inside an
  // already-carved-open pocket (like a gated reconnect spot positioned
  // right where an earlier dig already opened things up) reads as
  // floating in empty space instead of being embedded in something.
  // Always drawn first, regardless of what's already open around it.
  const backdropR = Math.max(rx, ry) * 1.5;
  ctx.fillStyle = "#241c14";
  pathFromPoints(irregularOvalPoints(cx, cy - ry * 0.15, backdropR, backdropR * 0.85, seed + 900, 0.3, 9));
  ctx.fill();
  ctx.fillStyle = "rgba(0,0,0,0.35)";
  pathFromPoints(irregularOvalPoints(cx, cy - ry * 0.15, backdropR * 0.92, backdropR * 0.78, seed + 901, 0.28, 9));
  ctx.fill();

  // a ragged, hand-torn outline instead of a perfect ellipse -- this alone
  // does most of the work of making it read as an actual hole in the dirt
  // rather than a sticker laid on top
  const raggedPts = irregularOvalPoints(cx, cy, rx, ry, seed, 0.22, 10);

  const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(rx, ry));
  grad.addColorStop(0, "rgba(150,120,75,0.55)");
  grad.addColorStop(0.65, "rgba(120,95,60,0.4)");
  grad.addColorStop(1, "rgba(80,62,40,0.12)");
  ctx.fillStyle = grad;
  pathFromPoints(raggedPts);
  ctx.fill();

  // a darker cavity right at the center -- gives the impression of actual
  // depth/recess instead of a flat tinted patch
  const cavityGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(rx, ry) * 0.55);
  cavityGrad.addColorStop(0, "rgba(20,14,8,0.5)");
  cavityGrad.addColorStop(1, "rgba(20,14,8,0)");
  ctx.fillStyle = cavityGrad;
  ctx.beginPath();
  ctx.ellipse(cx, cy, rx * 0.55, ry * 0.55, 0, 0, Math.PI * 2);
  ctx.fill();

  // a slow, subtle pulsing rim -- this is what actually marks it as a
  // real, interactive dig spot rather than just ambient dirt texture
  // (the surrounding dark blotches can look similar at a glance otherwise)
  const pulse = 0.35 + Math.sin(performance.now() * 0.0022 + seed) * 0.2;
  ctx.strokeStyle = `rgba(230,200,130,${pulse})`;
  ctx.lineWidth = 1.5;
  pathFromPoints(irregularOvalPoints(cx, cy, rx + 1.5, ry + 1.5, seed + 50, 0.22, 10));
  ctx.stroke();
  ctx.strokeStyle = "rgba(55,42,24,0.55)";
  ctx.lineWidth = 1.5;
  pathFromPoints(raggedPts);
  ctx.stroke();
  // loose crumbs of dirt sitting right at the torn edge, so the rim
  // itself looks disturbed/broken rather than a clean drawn line
  ctx.fillStyle = "rgba(60,46,28,0.6)";
  for (let i = 0; i < 5; i++) {
    const a = pseudoRandom(seed + 80 + i * 4.1) * Math.PI * 2;
    const rr = 0.95 + pseudoRandom(seed + 81 + i * 3.3) * 0.25;
    const px = cx + Math.cos(a) * rx * rr, py = cy + Math.sin(a) * ry * rr;
    ctx.beginPath();
    ctx.ellipse(px, py, 1.6 + pseudoRandom(seed + 82 + i) * 1.4, 1.1, a, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.strokeStyle = "rgba(80,62,36,0.4)";
  ctx.lineWidth = 1;
  for (let i = 0; i < 4; i++) {
    const a = pseudoRandom(seed + i * 3.1) * Math.PI * 2;
    const len = 0.45 + pseudoRandom(seed + i * 5.7) * 0.4;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(a) * rx * len, cy + Math.sin(a) * ry * len);
    ctx.stroke();
  }
}

function drawTunnelDigSpot(node, camX) {
  const sx = node.x - camX;
  if (sx < -30 || sx > canvas.width + 30) return;
  const cy = gy + cameraY - node.heightAboveGround;
  const isUp = node.dir === "up";
  const isSunken = node.dir === "sunken";
  // a trapdoor, and whatever it drops you into, both read as an opening
  // IN THE FLOOR rather than a doorway on a wall -- the default "side"
  // marker shape (taller than it is wide, same portal shape as every
  // ordinary wall-side dig) read wrong for something you fall through
  // rather than walk into ("should look more on the ground, like
  // horiz thinner ovals")
  const parentNode = TUNNEL_NODES.find(n => n.id === node.parent);
  const isFloorOpening = !!node.trapGap || !!node.shelfGap ||
    !!(parentNode && (parentNode.trapGap || parentNode.shelfGap));
  // "up" spots sit higher, tighter and taller (an actual vertical dig);
  // "sunken" spots are wider and squatter (reads as a low crawl-space).
  // Anchored to cy (the node's own actual height), not the raw ground
  // line -- for a ground-level node these are identical (cy === gy +
  // cameraY), but for an ELEVATED "side"/"sunken" node (like the raised
  // reward path) the marker used to draw itself all the way down at
  // ground level instead of up at the node's real position.
  const markY = isUp ? cy - 12 : cy - (isSunken ? 26 : (isFloorOpening ? 20 : 34));
  // "up" markers shrunk down (was 10x22) -- at the up-chain's tighter
  // vertical spacing, the old size left almost no visible dirt between
  // consecutive markers, so several frontier holes in a row read as one
  // smeared-together patch instead of distinct spots
  // s5uHole's own shelfGap marker wants to read as a wider, flatter hole
  // than a trapdoor's own gap ("make the vertical down hole a wider, more
  // flatter oval") -- scoped to shelfGap specifically so it doesn't
  // change the look of the existing trapdoors (uTopDrop/s5u5Drop).
  const isWideFloorOpening = !!node.shelfGap;
  const markRX = isUp ? 8 : (isSunken ? 22 : (isWideFloorOpening ? 34 : (isFloorOpening ? 23 : 15)));
  const markRY = isUp ? 15 : (isSunken ? 14 : (isWideFloorOpening ? 7 : (isFloorOpening ? 10 : 20)));

  // a low rock lip overhanging any sunken spot -- hints at the lower
  // ceiling without actually changing the (ground-level) collision
  if (isSunken) {
    ctx.fillStyle = "#1c1610";
    ctx.beginPath();
    ctx.moveTo(sx - 30, gy + cameraY - 46);
    ctx.quadraticCurveTo(sx, gy + cameraY - 58, sx + 30, gy + cameraY - 46);
    ctx.lineTo(sx + 30, gy + cameraY - 40);
    ctx.quadraticCurveTo(sx, gy + cameraY - 50, sx - 30, gy + cameraY - 40);
    ctx.closePath();
    ctx.fill();
  }

  if (!node.dug) {
    drawDigSoftSpot(sx, markY, markRX, markRY, node.x * 1.7 + (isUp ? 200 : 0));
  } else {
    // dug -- the oval clip carved into the dirt (see drawTunnelTownScene)
    // is what actually reveals the little opening here; this just adds
    // a few loose rocks/rubble inside it for texture, plus a small
    // permanent ledge under any raised spot so there's actually
    // something to stand/land on -- matching the physics floor in
    // applyPhysics, which bridges all the way back to an already-dug
    // parent at the same height instead of leaving separate islands
    if (!node.trapGap && !node.shelfGap) {
      // every dug opening used to just reveal the same flat shared cave
      // interior dead-on -- especially obvious on a frontier spot with
      // nothing dug past it yet, where the hole opened onto literally
      // nothing: no depth, no sense it led anywhere, just a flat dark
      // cutout. This pushes each opening's back wall in a little,
      // recessed and darkened toward whichever side continues on (away
      // from the parent you dug in from, or straight back for the first
      // wall opening), with a couple of faint converging side-wall
      // strokes -- reads as a short little tunnel alcove receding into
      // shadow, not a hole that just stops existing the instant it opens
      const recessDir = (!parentNode || node.parent === "wall") ? 1 : (Math.sign(node.x - parentNode.x) || 1);
      const backCx = sx + recessDir * markRX * 0.4;
      const backCy = markY + markRY * 0.08;
      const backGrad = ctx.createRadialGradient(backCx, backCy, 1, backCx, backCy, Math.max(markRX, markRY) * 0.95);
      backGrad.addColorStop(0, "rgba(4,3,2,0.92)");
      backGrad.addColorStop(1, "rgba(4,3,2,0)");
      ctx.fillStyle = backGrad;
      ctx.beginPath();
      ctx.ellipse(backCx, backCy, markRX * 0.78, markRY * 0.72, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "rgba(0,0,0,0.35)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(sx - markRX * 0.75, markY - markRY * 0.5);
      ctx.lineTo(backCx - markRX * 0.25, backCy - markRY * 0.35);
      ctx.moveTo(sx - markRX * 0.75, markY + markRY * 0.5);
      ctx.lineTo(backCx - markRX * 0.25, backCy + markRY * 0.35);
      ctx.moveTo(sx + markRX * 0.75, markY - markRY * 0.5);
      ctx.lineTo(backCx + markRX * 0.25, backCy - markRY * 0.35);
      ctx.moveTo(sx + markRX * 0.75, markY + markRY * 0.5);
      ctx.lineTo(backCx + markRX * 0.25, backCy + markRY * 0.35);
      ctx.stroke();
    }
    if (node.trapGap || node.shelfGap) {
      // a broken-through plank, not a normal ledge -- two short jagged
      // stubs with open dark air between them, so there's a visible tell
      // that this spot won't hold you before you actually step on it.
      // shelfGap (s5uHole) draws noticeably wider/flatter than a
      // trapdoor's own gap -- see isWideFloorOpening above.
      const plankHalf = isWideFloorOpening ? 44 : 30;
      const voidRX = isWideFloorOpening ? 34 : 20;
      const voidRY = isWideFloorOpening ? 6 : 9;
      const stubW = 16;
      const trapCy = gy + cameraY - node.heightAboveGround;
      ctx.fillStyle = "#4a3a2a";
      ctx.beginPath();
      ctx.moveTo(sx - plankHalf, trapCy - 5);
      ctx.lineTo(sx - plankHalf + stubW, trapCy - 6);
      ctx.lineTo(sx - plankHalf + stubW + 4, trapCy + 2);
      ctx.lineTo(sx - plankHalf, trapCy + 3);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(sx + plankHalf, trapCy - 5);
      ctx.lineTo(sx + plankHalf - stubW, trapCy - 7);
      ctx.lineTo(sx + plankHalf - stubW - 5, trapCy + 1);
      ctx.lineTo(sx + plankHalf, trapCy + 3);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = "rgba(140,120,90,0.35)";
      ctx.lineWidth = 1;
      ctx.stroke();
      // the gap itself -- pure dark void, so it reads as a hole, not dirt.
      // A hand-torn ragged outline (same technique as every dig-spot
      // marker) instead of a perfect ellipse -- a broken-through plank
      // wouldn't punch a geometrically clean oval, and the perfect-oval
      // version read as a sticker rather than an actual splintered gap.
      ctx.fillStyle = "#0c0a08";
      pathFromPoints(irregularOvalPoints(sx, trapCy + 4, voidRX, voidRY, node.x * 3.7 + 4100, 0.3, 10));
      ctx.fill();
    } else if (node.heightAboveGround > 0) {
      const mergedSpan = tunnelMergedLedgeSpan(node);
      const ledgeLeft = mergedSpan.left - camX, ledgeRight = mergedSpan.right - camX;
      // the whole merged group draws at ONE shared height (the lowest
      // node in the group), not each node's own -- otherwise a merged
      // pair like u1/u1r (heights 5 apart) each drew their own ledge and
      // it read as two planks stacked right on top of each other instead
      // of the single shelf the span-merge was supposed to produce.
      const ledgeCy = gy + cameraY - mergedSpan.height;
      // a couple of stubby support posts underneath, reaching down into
      // the dug pocket below the ledge -- without these, an elevated
      // ledge just floated in the dark with nothing visibly holding it
      // up. Only reaches as far as this node's own carved-out hole (not
      // all the way to true ground, which for a high climb would be way
      // outside the small revealed oval and get clipped away invisibly).
      const postBottom = ledgeCy + (TUNNEL_PASSAGE_HEIGHT / 2 + 6) - 4;
      ctx.strokeStyle = "#241c14";
      ctx.lineWidth = 4;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(ledgeLeft + 6, ledgeCy + 2);
      ctx.lineTo(ledgeLeft + 6, postBottom);
      ctx.moveTo(ledgeRight - 6, ledgeCy + 2);
      ctx.lineTo(ledgeRight - 6, postBottom);
      ctx.stroke();

      // a thicker, higher-contrast ledge -- brighter top surface, dark
      // underside -- so it actually reads clearly against the dark cave
      // background instead of blending in as a thin sliver
      ctx.fillStyle = "#5a4632";
      ctx.fillRect(ledgeLeft, ledgeCy - 6, ledgeRight - ledgeLeft, 6);
      ctx.fillStyle = "#241c14";
      ctx.fillRect(ledgeLeft, ledgeCy, ledgeRight - ledgeLeft, 4);
      ctx.strokeStyle = "rgba(140,120,90,0.5)";
      ctx.lineWidth = 1;
      ctx.strokeRect(ledgeLeft, ledgeCy - 6, ledgeRight - ledgeLeft, 6);
    }
    for (let i = 0; i < 4; i++) {
      const seed = node.x * 1.7 + i * 9.1;
      const rx = sx + (pseudoRandom(seed) - 0.5) * (isUp ? 16 : 30);
      const ry = (isUp ? cy - pseudoRandom(seed + 1) * 40 : gy + cameraY - pseudoRandom(seed + 1) * 20);
      ctx.fillStyle = pseudoRandom(seed + 2) < 0.5 ? "#4a3018" : "#241c14";
      ctx.beginPath();
      ctx.ellipse(rx, ry, 2.6 + pseudoRandom(seed + 3) * 2.6, 2, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    // a small pile of loose dirt clumps actually resting on the floor of
    // the hole -- distinct from the scattered rubble flecks above (those
    // float anywhere in the opening), this reads as "the stuff that got
    // dug out of here piled up at the bottom" instead of the hole just
    // being an empty void the moment it opens
    const floorY = gy + cameraY - node.heightAboveGround;
    for (let i = 0; i < 3; i++) {
      const seed = node.x * 2.3 + i * 13.7 + 5200;
      const px = sx + (pseudoRandom(seed) - 0.5) * 30;
      const pr = 4 + pseudoRandom(seed + 1) * 3;
      ctx.fillStyle = pseudoRandom(seed + 2) < 0.5 ? "#4a3018" : "#3a2814";
      pathFromPoints(irregularOvalPoints(px, floorY - pr * 0.4, pr, pr * 0.55, seed + 3, 0.3, 7));
      ctx.fill();
    }
  }
}

/* ------------------------------------------------------
   DIGGING FLOURISH -- a real brief animation (shovel swings, dirt
   kicks up) instead of the wall/spot instantly snapping to "dug" the
   moment space is pressed. Shared by both the wall and every branch
   spot, since it's the same action either way.
   ------------------------------------------------------ */
const TUNNEL_DIG_ANIM_DURATION = 1900; // slightly faster than the initial slow pass, still several real shovel-fulls
const TUNNEL_DIG_SWINGS = 5;
let activeDig = null; // { kind: "wall" | "spot", index, x, heightAboveGround, t }
// a brief floating hint shown when trying to dig a spot that's gated on
// something other than just having a shovel (a needsStone spot) --
// without this, trying to dig it just silently did nothing, which read
// as broken rather than "you're missing something"
const TUNNEL_BLOCKED_HINT_DURATION = 1800;
let tunnelBlockedHint = { active: false, x: 0, heightAboveGround: 0, t: 0 };

function drawDiggingFlourish(camX) {
  if (!activeDig) return;
  const p = Math.min(1, activeDig.t / TUNNEL_DIG_ANIM_DURATION);
  // used to anchor the whole flourish at "player position + a fixed 30px"
  // whenever facing the hole, instead of the hole's own x -- isPlayerNear
  // allows triggering a dig from up to 22px away, so any time the player
  // stopped short of dead-center on the spot, that fixed offset put the
  // shovel swing visibly to the side of the actual marked hole (worse
  // still on needsStone spots, where the stone-impact flash/sparks use
  // the real activeDig.x and the shovel didn't match it). Anchoring to
  // the hole itself, same as the turned-away branch already did, keeps
  // the swing landing on the real spot no matter where in that
  // tolerance band the player happened to stop.
  const holeDir = Math.sign(activeDig.x - (player.x + player.width / 2)) || (player.facing || 1);
  const faceDir = player.facing || 1;
  const facingHole = faceDir === holeDir;
  const sx = activeDig.x - camX;
  const sy = gy + cameraY - activeDig.heightAboveGround;
  // the swing/throw motion itself should always point INTO the hole --
  // when anchored at the player, that's their facing; when anchored at
  // the hole itself (player turned away), it's just the hole's own dig
  // direction, so the animation doesn't look like it's digging backwards
  const animDir = facingHole ? faceDir : holeDir;

  // a real three-part digging stroke each swing -- windup (raise back),
  // plunge (drive the blade down and forward into the dirt), then lift
  // and haul the loaded blade up and out -- instead of just rotating in
  // place, which read as the shovel wiggling rather than actually
  // digging anything
  const swingDur = TUNNEL_DIG_ANIM_DURATION / TUNNEL_DIG_SWINGS;
  const swingIndex = Math.min(TUNNEL_DIG_SWINGS - 1, Math.floor(activeDig.t / swingDur));
  const swingLocalT = Math.min(1, (activeDig.t - swingIndex * swingDur) / swingDur);

  let angle, bobY, bobX;
  if (swingLocalT < 0.3) {
    // windup -- raised back and up
    const t = swingLocalT / 0.3;
    angle = animDir * (-0.9 + t * 0.15);
    bobY = -7 * t;
    bobX = -4 * t * animDir;
  } else if (swingLocalT < 0.55) {
    // plunge -- drives down and forward into the ground
    const t = (swingLocalT - 0.3) / 0.25;
    angle = animDir * (-0.75 + t * 1.6);
    bobY = -7 + 11 * t;
    bobX = -4 * animDir + 8 * t * animDir;
  } else {
    // lift -- hauls the loaded blade back up and out, toward the throw
    const t = (swingLocalT - 0.55) / 0.45;
    angle = animDir * (0.85 - t * 0.65);
    bobY = 4 - 9 * t;
    bobX = 4 * animDir - 2 * t * animDir;
  }
  // for a needsStone spot, the stone itself is doing real work here, not
  // just sitting in the bag while the shovel does everything -- show it
  // wedged right into the hole, taking a little jolt on the plunge beat
  // of every swing, so using it up the moment the spot opens actually
  // reads as earned rather than an invisible inventory check
  const digNode = activeDig.kind === "spot" ? TUNNEL_NODES.find(n => n.id === activeDig.id) : null;
  // match drawTunnelDigSpot's own markY formula exactly, so the swing
  // actually lands on the marker glyph instead of floating a fixed
  // distance above the node's raw height -- that flat offset used to
  // assume every spot sat as high as an "up" node, so "side"/"sunken"
  // spots (whose markers sit noticeably lower, see markY above) had the
  // whole animation swinging into empty air several px above the actual
  // dig marker. The wall uses its own fixed 40 (see drawTunnelWall).
  const swingHeightOffset = activeDig.kind === "wall"
    ? 40
    : (digNode ? (digNode.dir === "up" ? 12 : (digNode.dir === "sunken" ? 26 : 34)) : 34);
  if (digNode && digNode.needsStone) {
    // pushed further still, per "a lil more theatrical" -- on top of the
    // existing jolt/flash: a fast expanding shockwave ring, a handful of
    // jagged stone-crack lines radiating out from the impact (not just
    // straight spark lines), and a heavier debris burst, all timed to
    // the same plunge beat so the stone reads as really taking a hit
    // rather than just glowing
    const stoneX = activeDig.x - camX;
    const baseY = sy - (swingHeightOffset - 8);
    const plunging = swingLocalT > 0.3 && swingLocalT < 0.6;
    const jolt = plunging ? (0.6 - Math.abs(swingLocalT - 0.45) * 6) * 8 : 0;
    const flash = plunging ? Math.max(0, 1 - Math.abs(swingLocalT - 0.45) * 10) : 0;
    if (flash > 0) {
      ctx.save();
      ctx.globalAlpha = flash * 0.75;
      ctx.fillStyle = "#fff8e0";
      ctx.beginPath();
      ctx.arc(stoneX, baseY - jolt, 16 + flash * 10, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // expanding shockwave ring -- starts tight at the impact and
      // rushes outward as the flash fades, instead of everything
      // happening at one fixed radius
      const ringT = 1 - flash; // 0 right at peak impact, 1 as it fades out
      ctx.save();
      ctx.globalAlpha = flash * 0.6;
      ctx.strokeStyle = "#fff8e0";
      ctx.lineWidth = 2 - ringT * 1.5;
      ctx.beginPath();
      ctx.arc(stoneX, baseY - jolt, 10 + ringT * 22, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();

      // jagged crack lines -- real broken angles instead of straight
      // spokes, reading as the stone actually fracturing under the hit
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * Math.PI * 2 + swingIndex * 1.7;
        const midA = a + (pseudoRandom(swingIndex * 31 + i) - 0.5) * 0.6;
        const len1 = 7 + flash * 5, len2 = 13 + flash * 10;
        const midX = stoneX + Math.cos(midA) * len1, midY = baseY - jolt + Math.sin(midA) * len1;
        const tipX = stoneX + Math.cos(a) * len2, tipY = baseY - jolt + Math.sin(a) * len2;
        ctx.strokeStyle = `rgba(60,50,40,${flash * 0.85})`;
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        ctx.moveTo(stoneX, baseY - jolt);
        ctx.lineTo(midX, midY);
        ctx.lineTo(tipX, tipY);
        ctx.stroke();
      }
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * Math.PI * 2 + swingIndex;
        ctx.strokeStyle = `rgba(255,240,200,${flash * 0.8})`;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(stoneX + Math.cos(a) * 10, baseY - jolt + Math.sin(a) * 10);
        ctx.lineTo(stoneX + Math.cos(a) * (16 + flash * 6), baseY - jolt + Math.sin(a) * (16 + flash * 6));
        ctx.stroke();
      }
      // a heavier scatter of dirt/stone debris chips, flung outward and
      // already fading -- separate from the shovel's own regular dirt
      // clump throw further below, so a stone hit visibly kicks up more
      if (flash > 0.15) {
        for (let i = 0; i < 6; i++) {
          const seed = swingIndex * 53.1 + i * 9.7;
          const a = pseudoRandom(seed) * Math.PI * 2;
          const dist = 10 + pseudoRandom(seed + 1) * 16;
          const chipX = stoneX + Math.cos(a) * dist;
          const chipY = baseY - jolt + Math.sin(a) * dist * 0.6 - 4;
          ctx.fillStyle = pseudoRandom(seed + 2) < 0.5 ? "#8a7358" : "#5c4a38";
          ctx.beginPath();
          ctx.ellipse(chipX, chipY, 1.6 + pseudoRandom(seed + 3) * 1.4, 1.2, a, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
    drawCollectible(ctx, stoneX, baseY - jolt, 15, jolt * 0.2, "stone");
  }

  // a soft burst of ground dust right as the blade drives in, on EVERY
  // swing (not just needsStone hits) -- before this the plunge landed
  // silently and the only dirt you ever saw was the clump thrown a beat
  // later, so the actual moment of impact read as weightless
  if (swingLocalT >= 0.28 && swingLocalT <= 0.62) {
    const dt = (swingLocalT - 0.28) / 0.34; // 0 at plunge start, 1 as the blade's lifting back out
    const puffAlpha = Math.sin(Math.min(1, Math.max(0, dt)) * Math.PI);
    if (puffAlpha > 0.03) {
      const puffY = sy - (swingHeightOffset - 10);
      ctx.save();
      ctx.globalAlpha = puffAlpha * 0.5;
      for (let i = 0; i < 4; i++) {
        const seed = swingIndex * 19.7 + i * 6.3;
        const a = Math.PI * 0.15 + (i / 4) * Math.PI * 0.7 - Math.PI * 0.42;
        const dist = 3 + dt * (7 + pseudoRandom(seed) * 6);
        const puffX = sx + Math.cos(a) * dist * animDir;
        const py = puffY - Math.abs(Math.sin(a)) * dist * 0.5 - dt * 2;
        ctx.fillStyle = pseudoRandom(seed + 1) < 0.5 ? "#6b4f33" : "#59402a";
        ctx.beginPath();
        ctx.ellipse(puffX, py, 2.4 + dt * 2.6 + pseudoRandom(seed + 2) * 1.4, 1.8 + dt * 1.6, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  drawShovelShape(ctx, sx + bobX, sy - swingHeightOffset + bobY, 13, angle);

  // each swing throws a real clump of dirt out in a visible arc (rises
  // then falls, tossed forward in whichever direction the player's
  // facing), timed to land right as the blade lifts out of the ground,
  // instead of a quick fading speck happening all at once. A denser mix
  // now -- a few heavier clods plus a scattering of finer flecks trailing
  // behind them, instead of four same-sized blobs, so a swing reads as a
  // real shovelful of dirt going somewhere rather than a token toss
  for (let s = 0; s < TUNNEL_DIG_SWINGS; s++) {
    const throwStart = s * swingDur + swingDur * 0.58;
    const throwDuration = swingDur * 0.75;
    const localT = activeDig.t - throwStart;
    if (localT < 0 || localT > throwDuration) continue;
    const lp = localT / throwDuration;
    const throwDir = animDir; // tossed forward, the same way the shovel's actually digging
    for (let i = 0; i < 6; i++) {
      const seed = s * 71.3 + i * 11.7;
      const spread = pseudoRandom(seed) * 10 - 5;
      const speed = 24 + pseudoRandom(seed + 1) * 22;
      const arcHeight = 22 + pseudoRandom(seed + 2) * 16;
      const clumpX = sx + throwDir * speed * lp + spread;
      const clumpY = sy - (swingHeightOffset - 6) - Math.sin(lp * Math.PI) * arcHeight;
      ctx.globalAlpha = 1 - lp * 0.25;
      ctx.fillStyle = pseudoRandom(seed + 3) < 0.5 ? "#4a3018" : "#3a2814";
      ctx.beginPath();
      ctx.ellipse(clumpX, clumpY, 3 + pseudoRandom(seed + 4) * 2.4, 2.6, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    // finer trailing flecks -- smaller, thrown a touch further and
    // faster, fading out quicker than the main clods so the spray has
    // real depth instead of every piece landing together
    for (let i = 0; i < 5; i++) {
      const seed = s * 137.9 + i * 23.1 + 400;
      const spread = pseudoRandom(seed) * 14 - 7;
      const speed = 34 + pseudoRandom(seed + 1) * 28;
      const arcHeight = 16 + pseudoRandom(seed + 2) * 14;
      const fleckX = sx + throwDir * speed * lp + spread;
      const fleckY = sy - (swingHeightOffset - 4) - Math.sin(lp * Math.PI) * arcHeight;
      ctx.globalAlpha = Math.max(0, 0.85 - lp * 0.9);
      ctx.fillStyle = pseudoRandom(seed + 3) < 0.5 ? "#5c4527" : "#3a2814";
      ctx.beginPath();
      ctx.ellipse(fleckX, fleckY, 1 + pseudoRandom(seed + 4) * 1, 0.9, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }
}

// a small gnarly root, poking out from a patch of dirt -- a curved main
// strand with one or two thinner branch forks, distinct from the
// straight crack-lines already scattered through the dirt texture
function drawRootStrand(cx, cy, len, seed, color) {
  ctx.strokeStyle = color || "rgba(120,95,60,0.5)";
  ctx.lineWidth = 1.3;
  const ang = pseudoRandom(seed) * Math.PI * 2;
  const midX = cx + Math.cos(ang) * len * 0.55 + (pseudoRandom(seed + 1) - 0.5) * len * 0.4;
  const midY = cy + Math.sin(ang) * len * 0.55 + (pseudoRandom(seed + 2) - 0.5) * len * 0.4;
  const endX = cx + Math.cos(ang) * len, endY = cy + Math.sin(ang) * len;
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.quadraticCurveTo(midX, midY, endX, endY);
  ctx.stroke();
  if (pseudoRandom(seed + 3) < 0.6) {
    ctx.lineWidth = 0.8;
    const forkX = midX + Math.cos(ang + 0.9) * len * 0.3;
    const forkY = midY + Math.sin(ang + 0.9) * len * 0.3;
    ctx.beginPath();
    ctx.moveTo(midX, midY);
    ctx.lineTo(forkX, forkY);
    ctx.stroke();
  }
}

// the permanent wedge of dirt hanging in the middle of the up-chain loop
// -- point down, wide at top, tucked into the real gap left between the
// left leg (u1 -> u1s1 -> u1s2 -> uTop) and right leg (u1 -> u2 -> u3).
// Fixed in world space (x, heightAboveGround -- same coordinate space as
// every TUNNEL_NODE), and never affected by dig state -- this is dirt
// that simply never comes out. Bigger than the original pass, with real
// breathing room around it, AND actually solid now -- see
// tunnelCoreMoundContains below, which the player collision checks
// against directly, since being purely decorative meant you could just
// walk straight through it.
const TUNNEL_CORE_MOUND_SEED = 41000;
// kept clear of every surrounding node's own tube corridor (u1s1/u1s2 on
// the left, u2/u3 on the right, uTop above) with real margin on all
// sides -- the actual open gap between those corridors pinches down to
// almost nothing near the very bottom and the very top, so this is sized
// to fill as much of the safely-open middle as it can without eating
// into any node's own dig space
const TUNNEL_CORE_MOUND_BASE_PTS = [
  { x: 765, y: 120 }, // bottom point -- shifted +150 along with the whole dig graph/elders move
  { x: 712, y: 172 },
  { x: 708, y: 232 }, // top-left
  { x: 758, y: 252 },
  { x: 772, y: 225 }, // top-right
  { x: 798, y: 178 }
];

// the same jitter every time (seeded purely by index, not time), so the
// collision shape and the rendered shape are always identical
function tunnelCoreMoundWorldPoints() {
  return TUNNEL_CORE_MOUND_BASE_PTS.map((p, i) => {
    const jx = (pseudoRandom(TUNNEL_CORE_MOUND_SEED + i * 6.1) - 0.5) * 10;
    const jy = (pseudoRandom(TUNNEL_CORE_MOUND_SEED + i * 6.1 + 3) - 0.5) * 10;
    return { x: p.x + jx, h: p.y + jy };
  });
}

// standard ray-casting point-in-polygon test, in world (x, heightAboveGround) space
function tunnelCoreMoundContains(x, h) {
  const pts = tunnelCoreMoundWorldPoints();
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const pi = pts[i], pj = pts[j];
    if (((pi.h > h) !== (pj.h > h)) &&
        (x < (pj.x - pi.x) * (h - pi.h) / (pj.h - pi.h) + pi.x)) {
      inside = !inside;
    }
  }
  return inside;
}

function drawTunnelCoreMound(camX) {
  const worldPts = tunnelCoreMoundWorldPoints();
  const screenPts = worldPts.map(p => ({ x: p.x - camX, y: gy + cameraY - p.h }));
  if (screenPts.every(p => p.x < -40) || screenPts.every(p => p.x > canvas.width + 40)) return;
  const seedBase = TUNNEL_CORE_MOUND_SEED;

  ctx.save();
  pathFromPoints(screenPts);
  ctx.clip();

  ctx.fillStyle = "#241c14";
  ctx.fillRect(screenPts[0].x - 60, Math.min(...screenPts.map(p => p.y)) - 20, 140, 140);

  // a little internal shading so it reads as a rounded mass, not a flat cutout
  const cx = screenPts.reduce((s, p) => s + p.x, 0) / screenPts.length;
  const cy = screenPts.reduce((s, p) => s + p.y, 0) / screenPts.length;
  const shade = ctx.createRadialGradient(cx, cy - 15, 4, cx, cy, 55);
  shade.addColorStop(0, "rgba(90,72,50,0.4)");
  shade.addColorStop(1, "rgba(0,0,0,0.25)");
  ctx.fillStyle = shade;
  ctx.beginPath();
  ctx.ellipse(cx, cy, 55, 55, 0, 0, Math.PI * 2);
  ctx.fill();

  // a couple of embedded rocks and root strands so it matches the rest
  // of the dirt's texture instead of reading as a flat silhouette
  for (let i = 0; i < 3; i++) {
    const seed = seedBase + 100 + i * 19.3;
    const rx = cx + (pseudoRandom(seed) - 0.5) * 70;
    const ry = cy + (pseudoRandom(seed + 1) - 0.5) * 70;
    const rr = 3 + pseudoRandom(seed + 2) * 5;
    ctx.fillStyle = pseudoRandom(seed + 3) < 0.5 ? "#6a6154" : "#453d32";
    ctx.beginPath();
    ctx.ellipse(rx, ry, rr, rr * 0.8, pseudoRandom(seed + 4) * Math.PI, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,0.12)";
    ctx.beginPath();
    ctx.ellipse(rx - rr * 0.3, ry - rr * 0.3, rr * 0.35, rr * 0.25, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  for (let i = 0; i < 3; i++) {
    const seed = seedBase + 300 + i * 23.7;
    drawRootStrand(cx + (pseudoRandom(seed) - 0.5) * 60, cy + (pseudoRandom(seed + 1) - 0.5) * 60, 16 + pseudoRandom(seed + 2) * 12, seed);
  }

  ctx.restore();
}

function drawTunnelTownScene(camX) {
  // nothing past the undug wall should be visible at all -- clip
  // everything "room" related to the currently-revealed width (just
  // the wall itself while it's solid, the full room once it's open),
  // then paint flat solid earth over whatever's left of the screen so
  // there's no glimpse of beams/floor/etc. leaking through from an
  // area that hasn't been dug into yet
  // start from solid earth everywhere -- the real room only shows
  // through the entry nook plus small oval "openings" carved along
  // whatever's actually been dug, connected by narrow tunnel tubes.
  // NOT a wide flood-lit region that jumps open all at once.
  drawDetailedDirtFill(0, canvas.width, canvas.height, 9000, camX);

  ctx.save();
  ctx.beginPath();
  const nookRightScreen = Math.round(TUNNELTOWN_WALL_X - camX);
  ctx.rect(-20, 0, nookRightScreen + 20, canvas.height); // the starting nook, always open

  if (tunnelWallBroken) {
    addTunnelHoleToPath(camX, TUNNELTOWN_WALL_X + 16, 0);
    TUNNEL_NODES.forEach(node => {
      if (!tunnelNodeParentDug(node)) return; // only carve as far as what's actually reachable
      const parentPos = tunnelNodeParentPos(node);
      if (parentPos) addTunnelTubeToPath(camX, parentPos.x, parentPos.h, node.x, node.heightAboveGround);
      addTunnelHoleToPath(camX, node.x, node.heightAboveGround);
    });
  }

  ctx.clip();

  // cooler, greyer earth tones than the mole hole's warm soil-orange --
  // this place reads as older, damper, less lived-in. Ground line
  // (gy + cameraY) scrolls downward as the player climbs, so the sky
  // fill has to stretch to cover the newly-revealed space above it.
  const groundY = gy + cameraY;
  const sky = ctx.createLinearGradient(0, 0, 0, groundY);
  sky.addColorStop(0, "#2e2620");
  sky.addColorStop(1, "#161210");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, groundY);

  // the permanent dirt core hanging in the middle of the up-chain loop --
  // drawn right on top of the open sky fill, so it reads as a real solid
  // mass sitting inside the carved-open cave, never removed by any digging
  drawTunnelCoreMound(camX);

  // rougher wall texture -- less regular than the mole hole's neat
  // packed-earth bands, more like crumbling old digging
  ctx.strokeStyle = "rgba(90,80,70,0.2)";
  ctx.lineWidth = 1;
  for (let i = 0; i < 5; i++) {
    const wy = 25 + i * 50;
    ctx.beginPath();
    ctx.moveTo(0, wy);
    for (let x = 0; x <= canvas.width; x += 35) {
      ctx.lineTo(x, wy + Math.sin((x + i * 60) * 0.025) * 6 + pseudoRandom(x + i * 13) * 3);
    }
    ctx.stroke();
  }

  // the old leaning support-beam props (three of them, at x560/780/1000)
  // were removed per direct feedback -- they were just a bare leaning
  // pole plus a short diagonal brace, not actually holding up anything
  // overhead, which read as "kind of out of place" rather than a real
  // structural prop ("this tunneltown shaft also kinda out of
  // place...not holding anything up, lets remove"). No replacement --
  // removing was the preferred fix over building them out into real
  // (much taller) roof supports.

  // branch dig spots -- each one only drawn once its OWN parent has
  // actually been dug, so you only ever see the frontier you've earned.
  // s5uNook skipped here on purpose: it's a real landing floor (physics
  // still catches the player on it), but it auto-dugs the instant s5uHole
  // does, right underneath it -- drawing its own separate ledge/marker
  // there read as a second, redundant little platform stacked directly
  // under the hole ("remove the mini platform right under the new
  // vertical hole"). No marker, no rubble -- just a plain cave floor to
  // land on, with the reward now visible sitting there instead (see the
  // rewardHeight special-case in updateTunnelTownScene's dig-complete block).
  TUNNEL_NODES.forEach(node => {
    if (node.id === "s5uNook") return;
    if (tunnelNodeParentDug(node)) drawTunnelDigSpot(node, camX);
  });

  // ground
  ctx.fillStyle = "#181310";
  ctx.fillRect(0, groundY, canvas.width, canvas.height - groundY);
  ctx.strokeStyle = "rgba(90,80,70,0.35)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, groundY);
  ctx.lineTo(canvas.width, groundY);
  ctx.stroke();

  // dim pebble/rubble scatter along the floor
  for (let i = 0; i < 30; i++) {
    const seed = i * 23.1 + 700;
    const px = i * (TUNNELTOWN_WIDTH / 30) + pseudoRandom(seed) * 26 - camX;
    if (px < -10 || px > canvas.width + 10) continue;
    ctx.fillStyle = "rgba(90,80,70,0.45)";
    ctx.beginPath();
    ctx.ellipse(px, groundY + 4 + pseudoRandom(seed + 1) * 4, 2.2 + pseudoRandom(seed + 2) * 2, 1.5, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  // exit -- climb back up to the mole hole
  const ex = tunnelTownExit.x - camX;
  const beam = ctx.createLinearGradient(ex, 0, ex, groundY);
  beam.addColorStop(0, "rgba(200,180,150,0.25)");
  beam.addColorStop(1, "rgba(200,180,150,0)");
  ctx.fillStyle = beam;
  ctx.beginPath();
  ctx.moveTo(ex - 24, 0);
  ctx.lineTo(ex + 24, 0);
  ctx.lineTo(ex + 9, groundY);
  ctx.lineTo(ex - 9, groundY);
  ctx.closePath();
  ctx.fill();

  drawTunnelTownExitSign(ex, groundY);

  ctx.restore(); // end of the carve clip -- everything outside the nook/ovals/tubes stays solid dirt

  // the dirt-pile-with-shovel prop -- moved here from the mole hole,
  // where it read as out of place next to the tidy market row. An
  // actual dig in progress is exactly where a discarded shovel belongs.
  drawMoleholeDirtPile(camX, TUNNELTOWN_DIRT_PILE_X, groundY);

  // the elders, sitting right where the passage dead-ends -- drawn
  // after the clip/fill above so they're never accidentally clipped
  drawElderTrio(camX);

  // the blockage itself -- solid until dug, then a broken opening into
  // the branch dig area beyond -- also drawn after, on top of the flat
  // fill, so its own detail (the marked soft spot, the rubble) shows
  drawTunnelWall(camX);

  drawDiggingFlourish(camX);
  drawTunnelBlockedHint(camX);

  // speech bubble drawn dead last so it's never covered by the wall or
  // anything else in the scene
  drawElderSpeechBubble(camX);
}

// a short-lived floating callout when the player tries to dig something
// that's gated on more than just the shovel -- fades in, holds, fades out
function drawTunnelBlockedHint(camX) {
  if (!tunnelBlockedHint.active) return;
  const p = tunnelBlockedHint.t / TUNNEL_BLOCKED_HINT_DURATION;
  const fade = p < 0.15 ? p / 0.15 : (p > 0.75 ? (1 - p) / 0.25 : 1);
  const sx = tunnelBlockedHint.x - camX;
  const sy = gy + cameraY - tunnelBlockedHint.heightAboveGround - 46;
  ctx.globalAlpha = Math.max(0, fade);
  drawFittedSpeechBubble(ctx, sx - 60, sy - 30, ["This spot feels too solid to dig...", "a stone wedged in with the shovel might work it loose."]);
  ctx.globalAlpha = 1;
}

function updateTunnelTownScene(deltaTime) {
  // vertical camera -- follows the player upward once they've climbed
  // past a comfortable on-screen height, so stacked jumps/platforms
  // aren't capped by a single screen's ~250-unit ceiling. Mirrors the
  // horizontal cameraX = Math.max(0, player.x - canvas.width*0.4)
  // pattern used elsewhere, just on the vertical axis. Reset to 0 on
  // any scene change (see the season-transition handler).
  cameraY = Math.max(0, player.y - 150);

  elderTrio.forEach(updateNPCIdle); // the same light idle bounce every other NPC has

  wallBreakPoofT += deltaTime * 1000;
  if (tunnelBlockedHint.active) {
    tunnelBlockedHint.t += deltaTime * 1000;
    if (tunnelBlockedHint.t >= TUNNEL_BLOCKED_HINT_DURATION) tunnelBlockedHint.active = false;
  }

  // mid-dig -- the actual wall-break/spot-dug state change only lands
  // once the flourish finishes, not the instant space is pressed
  if (activeDig) {
    activeDig.t += deltaTime * 1000;
    if (activeDig.t >= TUNNEL_DIG_ANIM_DURATION) {
      if (activeDig.kind === "wall") {
        tunnelWallBroken = true;
        wallBreakPoofT = 0;
        elderThanksQueued = true;
      } else {
        const node = TUNNEL_NODES.find(n => n.id === activeDig.id);
        node.dug = true;
        // s5uHole used to also auto-dig s5uNook as a floor to catch the
        // player one short hop below -- but with no ledge marker drawn
        // there (see the render skip above, "remove the mini platform
        // right under the new vertical hole"), landing on that invisible
        // floor just read as stopping and floating in mid-air with
        // nothing visibly holding them up. Per direct feedback ("lets
        // fall all the way down this vertical hole"), s5uNook is no
        // longer dug at all -- the hole just opens straight through with
        // no floor waiting underneath, and gravity carries the player
        // the rest of the way down to real ground, same as any other
        // undug gap in tunnel town. s5uNook itself is left in
        // TUNNEL_NODES inert (parented off the map/frontier flow
        // already) rather than deleted, in case a real floor down there
        // is wanted again later.
        // step the player up onto their own newly-dug platform, if this
        // was an elevated ("up"/"side") spot and they're sitting
        // somewhere below it -- without this, digging one of these was
        // possible from anywhere within the dig-trigger's own generous
        // +-25 vertical tolerance (isPlayerNear, used to decide whether
        // space-near-the-spot counts at all), but the SEPARATE general
        // ledge-landing check only ever catches a player within -14 of
        // the platform's own top. Trigger from, say, 17-20 units below
        // (well within the dig range, verified via a scripted approach-
        // and-dig simulation) and the dig itself succeeds -- the hole
        // visibly opens, the item pops out -- but the player keeps
        // falling right through the brand new platform because they'd
        // already sunk past the landing check's narrower catch zone
        // before it finished. They'd end up back on the ground below,
        // looking up at a shelf they'd JUST dug, unable to reach it --
        // reads exactly like standing in "packed dirt that can't be
        // dug" once landed, since the real platform is now out of
        // reach above them. This snap guarantees the two tolerances
        // always agree: however you triggered the dig, you land on
        // what you dug.
        if (node.heightAboveGround > 0 &&
            Math.abs((player.x + player.width / 2) - node.x) <= 30 &&
            player.y <= node.heightAboveGround) {
          const { height: platformTop } = tunnelMergedLedgeSpan(node);
          player.y = platformTop;
          player.vy = 0;
          player.jumping = false;
          player.usedDoubleJump = false;
        }
        if (node.hasItem) {
          // was never converted into actual screen space (just the raw
          // heightAboveGround + 14, treated as if that WERE a screen y) --
          // it was popping into existence off in the corner of the canvas
          // instead of at the dig spot, which is exactly why it was never
          // visible sitting in the dirt before flying off. Needs the same
          // gy + cameraY - height conversion every other tunnel-town draw uses.
          // s5uHole's own reward reveals down at s5uNook's height instead of
          // its own -- the hole opens up top but the player is about to fall
          // straight through it, so revealing the aragonite up at the hole
          // means it's already mid-flight to the basket before they ever see
          // it. Revealing it down in the pocket instead means it's still
          // sitting there, visible, for the ~70px drop on the way down.
          const rewardHeight = node.id === "s5uHole"
            ? (TUNNEL_NODES.find(n => n.id === "s5uNook")?.heightAboveGround ?? node.heightAboveGround)
            : node.heightAboveGround;
          const revealY = gy + cameraY - rewardHeight - 14;
          // a beat longer than the default reveal -- these are found buried
          // in dirt, easy to miss entirely if it flies off immediately
          startCollectAnimation({ x: node.x, y: revealY, size: 8, rotation: 0 }, node.itemType || "cushionPart", null, 900);
        }
        // the stone is what actually breaks a needsStone spot open, not
        // just the shovel with the stone incidentally sitting in your bag --
        // it gets used up right here, the same moment the hole opens
        if (node.needsStone) {
          inventory.stone -= 1;
          if (inventory.stone <= 0) {
            delete inventory.stone;
            if (heldItem === "stone") heldItem = null;
          }
          updateInventoryUI();
        }
      }
      activeDig = null;
    }
    return; // nothing else happens while a dig is in progress
  }

  if (elderDialogue.active) {
    // same walk-away auto-close as the mole-hole NPCs -- otherwise the
    // speech bubble just sits at the elders' fixed spot forever once you
    // wander off mid-conversation, never actually dismissed
    if (!isPlayerNear(ELDER_X, 0, 150, 90, 90)) {
      elderDialogue.active = false;
    } else {
      if (keys.spaceJustPressed) advanceElderDialogue();
      return; // mid-conversation -- don't also process digging/exit this frame
    }
  }

  if (isPlayerNear(ELDER_X, 0, 35, 25, 20) && keys.spaceJustPressed) {
    startElderDialogue();
    return;
  }

  if (!tunnelWallBroken) {
    // only diggable once the elders have actually explained what's
    // going on -- ties the action to the ask instead of just being a
    // wall you happen to have a shovel for
    if (elderTalkedTo && heldItem === "shovel" && keys.spaceJustPressed && isPlayerNear(TUNNELTOWN_WALL_X + 16, 0, 26, 20, 20)) {
      activeDig = { kind: "wall", x: TUNNELTOWN_WALL_X + 16, heightAboveGround: 0, t: 0 };
    }
  } else {
    // only nodes whose own parent is already dug are reachable at all --
    // matches what's actually drawn/visible
    TUNNEL_NODES.forEach(node => {
      if (node.dug || !tunnelNodeParentDug(node)) return;
      const nearSpot = isPlayerNear(node.x, node.heightAboveGround, 22, 25, 25);
      // the reconnect back down toward u1 also needs the stone in hand --
      // that's what makes it a real find, not just another shovel-dig.
      // Trying to dig it without the stone used to just silently do
      // nothing, which read as broken rather than "missing something" --
      // now it surfaces an actual hint instead of failing silently.
      if (node.needsStone && !(inventory.stone > 0)) {
        if (heldItem === "shovel" && keys.spaceJustPressed && nearSpot) {
          tunnelBlockedHint.active = true;
          tunnelBlockedHint.x = node.x;
          tunnelBlockedHint.heightAboveGround = node.heightAboveGround;
          tunnelBlockedHint.t = 0;
        }
        return;
      }
      if (heldItem === "shovel" && keys.spaceJustPressed && nearSpot) {
        activeDig = { kind: "spot", id: node.id, x: node.x, heightAboveGround: node.heightAboveGround, t: 0 };
      }
    });
  }

  if (keys.spaceJustPressed && isPlayerNear(tunnelTownExit.x, 0, 24, 15, 15)) {
    startSeasonTransition("molehole");
  }
}

function drawCloudsScene(camX) {
  // multi-stop sky — deeper blue up top, fading toward near-white
  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, "#a9d4f0");
  sky.addColorStop(0.35, "#c9e6f5");
  sky.addColorStop(0.65, "#e8f5fc");
  sky.addColorStop(1, "#fbfdff");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // varied background cloud shapes, not just repeats of one silhouette
  cloudsDecor.forEach(c => drawBackgroundCloud(c.x, c.y, c.scale, c.type, camX * 0.3));

  drawCrows(camX); // same birds, consistent across every zone
  drawPlane(camX);

  // ground here IS cloud — soft and pale, not the usual grass/dirt
  const groundGrad = ctx.createLinearGradient(0, gy, 0, gy + 60);
  groundGrad.addColorStop(0, "#f0f8ff");
  groundGrad.addColorStop(1, "#dceef8");
  ctx.fillStyle = groundGrad;
  ctx.fillRect(-camX, gy, canvas.width + camX, canvas.height - gy);

  // soft rolling texture so the surface doesn't read as flat
  ctx.fillStyle = "rgba(255,255,255,0.7)";
  for (let i = -2; i < 8; i++) {
    const bx = i * 180 - camX % 180;
    ctx.beginPath();
    ctx.ellipse(bx, gy + 4, 95, 18, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = "rgba(200,225,245,0.35)";
  for (let i = -2; i < 8; i++) {
    const bx = i * 180 - camX % 180 + 60;
    ctx.beginPath();
    ctx.ellipse(bx, gy + 14, 60, 10, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  drawHole(cloudHole.x, cloudHole.width, camX); // same visual language as spring's holes
  if (elephantSpot.piecesPlaced >= 8) {
    drawHole(elephantHole.x, elephantHole.width, camX);
  }

  hopClouds.forEach(c => drawHopCloud(c, camX));
  drawCrystalOnCloud(camX);
  drawWaterDrips(camX);
  drawRabbitShuttleCloud(camX);
  drawSimpleCloudPieces(camX);
  drawPeanut(camX);
  vaultClouds.forEach(v => drawVaultCloud(v, camX));
  drawElephantSpot(camX);
  drawBalloonNPC(camX);
}

function updateCloudsScene(deltaTime) {
  if (fallState.active) return; // handled globally by updateFallState

  updateWaterDrips(deltaTime);
  updateRabbitShuttle(deltaTime);
  updatePlane(cameraX);
  updateFallingCloudPieces(deltaTime);
  updatePeanutFall(deltaTime);
  updatePeanutPickup();
  updateSimpleCloudPiecePickups();
  vaultClouds.forEach((v, i) => updateVaultCloud(v, i, deltaTime));
  updateElephantSpot(deltaTime);
  updateBalloonNPC(deltaTime);

  // mount via spacebar — same interact key as everything else, so it
  // stays free for picking things up while riding, not claimed by mounting.
  // Only mountable while DOCKED — that's the whole point of the dock pause,
  // so you never have to time a moving target
  if (!rabbitShuttle.mounted && !player.launched && rabbitShuttle.state === "docked") {
    if (pressedDownNear(rabbitShuttle.currentX, rabbitShuttle.currentHeight, 40, 30, 30)) {
      rabbitShuttle.mounted = true;
    }
  }

  // CRYSTAL PICKUP — same shape as tulip/boomerang's pickup
  if (!crystal.collected && !crystal.collecting) {
    if (pressedDownNear(crystal.x, crystal.heightAboveGround, 26, 15, 25)) {
      crystal.collecting = true;
      startCollectAnimation(
        { x: crystal.x, y: gy - crystal.heightAboveGround, size: 11, rotation: 0 },
        "crystal"
      );
    }
  }

  if (player.y <= 0) {
    const playerCenterX = player.x + player.width / 2;
    const overOriginalHole = playerCenterX > cloudHole.x && playerCenterX < cloudHole.x + cloudHole.width;
    const overElephantHole = elephantSpot.piecesPlaced >= 8 &&
      playerCenterX > elephantHole.x && playerCenterX < elephantHole.x + elephantHole.width;

    if (overOriginalHole || overElephantHole) {
      const hole = overOriginalHole ? cloudHole : elephantHole;
      player.x = hole.x + hole.width / 2 - player.width / 2; // center on the hole, not wherever the trigger fired
      fallState.active = true;
      fallState.t = 0;
      fallState.mode = "cloudHole";
    }
  }
}

function draw(){
ctx.clearRect(0,0,canvas.width,canvas.height);

if (bookReader.active || bookReader.opening || bookReader.closing) {
  drawBookReader();
} else if (corkboardReader.active || corkboardReader.opening || corkboardReader.closing) {
  drawCorkboardReader();
} else if (carvingUI.active || carvingUI.opening || carvingUI.closing) {
  drawCarvingUI();
} else if (camera.topDown) {
  ctx.fillStyle="rgba(245,245,240,0.94)";
  ctx.fillRect(0,0,canvas.width,canvas.height);
  ctx.fillStyle="#2b2b2b";
  ctx.fillText("Orchard → Paths",120,120);
} else {

const camX = cameraX;

if (currentScene === "autumn") {
  drawAutumnScene(camX);
} else if (currentScene === "spring") {
  drawSpringScene(camX);
} else if (currentScene === "forest") {
  drawForestScene(camX);
} else if (currentScene === "clouds") {
  drawCloudsScene(camX);
} else if (currentScene === "oak") {
  drawOakScene(camX);
} else if (currentScene === "ratroom") {
  drawRatRoomScene(camX);
} else if (currentScene === "molehole") {
  drawMoleholeScene(camX);
} else if (currentScene === "tunneltown") {
  drawTunnelTownScene(camX);
}

// worn/in-progress crown — shared across scenes, drawn here so it shows
// (and C keeps working) no matter which zone you're actually standing in

// flying (collecting/placing) items — shared across scenes, drawn here so
// a pickup animation started in ANY scene actually renders, not just autumn's
flyingItems.forEach(f => {
  // a bright radiating glow + a few outward sparkle flecks behind
  // anything mid-reveal -- the oversized pop alone still wasn't enough
  // to catch the eye against a dark, busy dirt background, so this adds
  // actual light where there wasn't any, which is what real attention-
  // grabbing "you found something" moments need underground
  if (f.phase === "reveal") {
    const fx = f.x - camX, fy = f.y;
    const glowP = Math.min(f.t / (f.revealDuration * 0.35), 1);
    const glowR = (f.size * f.scale) * (2.5 + glowP * 1.5);
    const glow = ctx.createRadialGradient(fx, fy, 0, fx, fy, glowR);
    glow.addColorStop(0, "rgba(255,240,180,0.55)");
    glow.addColorStop(0.5, "rgba(255,215,120,0.25)");
    glow.addColorStop(1, "rgba(255,215,120,0)");
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(fx, fy, glowR, 0, Math.PI * 2);
    ctx.fill();
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2 + f.t * 0.002;
      const dist = (glowR * 0.55) * (0.6 + 0.4 * Math.sin(f.t * 0.006 + i));
      ctx.fillStyle = "rgba(255,245,210,0.85)";
      ctx.beginPath();
      ctx.ellipse(fx + Math.cos(a) * dist, fy + Math.sin(a) * dist, 1.8, 1.8, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  if (f.itemType === "leaf" && f.extra) {
    drawLeafShape(ctx, f.x - camX, f.y, f.size * f.scale, f.rotation, f.extra.shape, f.extra.color);
  } else {
    drawCollectible(ctx, f.x - camX, f.y, f.size * f.scale, f.rotation, f.itemType);
  }
});

drawBoomerangThrow(camX); // the boomerang itself, while it's in the air

/* PLAYER */
const px = player.x - camX;
// cameraY is ADDED here (not subtracted): as the player climbs past the
// follow threshold in tunnel town, cameraY grows to offset player.y 1:1,
// pinning the sprite's on-screen height instead of letting it keep
// rising off the top of the canvas -- the world (ground line, walls,
// etc.) scrolls away underneath instead. A no-op everywhere else, since
// cameraY is always 0 outside tunnel town.
const py = gy + cameraY - player.height - player.y;

// while falling through a hole, the body actually MOVES downward — it
// isn't frozen in place; only what crosses below ground level (gy) gets
// clipped away, so it reads as sinking into the hole rather than a static cutoff
const fallProgress = fallState.active ? Math.min(fallState.t / fallDurationForMode(fallState.mode), 1) : (fallJustEndedIntoTransition ? 1 : 0);
const sinkAmount = fallProgress * (player.height + 20); // how far down the body has moved
const drawPy = py + sinkAmount;

// shadow shrinks along with the body sinking in -- pinned to the
// visual ground line, which itself scrolls with cameraY in tunnel
// town's climbing shaft (a no-op everywhere else, since cameraY is 0)
ctx.fillStyle = `rgba(60,40,20,${0.18 * (1 - fallProgress)})`;
ctx.beginPath();
ctx.ellipse(px + player.width/2, gy + cameraY + 5, 18 * (1 - fallProgress * 0.5), 6 * (1 - fallProgress * 0.5), 0, 0, Math.PI*2);
ctx.fill();
// ground contact tint
ctx.fillStyle = `rgba(90,70,40,${0.08 * (1 - fallProgress)})`;
ctx.beginPath();
ctx.ellipse(px + player.width/2, gy + cameraY + 6, 22, 8, 0, 0, Math.PI*2);
ctx.fill();

if (drawPy < gy + cameraY) { // still at least partly above ground — worth drawing
  ctx.save();
  ctx.beginPath();
  // widened well past the sprite's own bounding box -- the clip only
  // NEEDS to hide what's below ground (the gy cutoff, for the
  // hole-fall sink effect), not hug the sprite horizontally. A tight
  // +/-2px margin was fine for an upright box, but once the clockwork
  // grove's ride-tilt rotates the sprite even a bounded amount, its
  // corners swing outside that margin and get visibly chopped off by
  // this same clip. Generous horizontal padding costs nothing since
  // there's nothing else in this narrow vertical strip to accidentally
  // reveal.
  ctx.rect(px - 24, 0, player.width + 48, gy); // only the region above ground level is visible
  ctx.clip();

  // woozy sway -- a gentle wobble on the body itself while stunned
  // from a hard fall, nested inside the clip so the clip region
  // itself stays axis-aligned and only the sprite tilts. Also carries
  // forestGearRideAngle -- the forest clockwork grove's spinning gears
  // tilt the player's sprite along with the turn while riding one (see
  // updateForestScene). The two never really overlap in practice, so
  // just summing them is fine.
  ctx.save();
  const swayAngle = playerWoozyT > 0 ? Math.sin(performance.now() * 0.009) * 0.28 * (playerWoozyT / WOOZY_MS) : 0;
  // a little lean during the mine cart's tip/sink ending, scaled down
  // from the cart's own tipAngle -- the player used to stay perfectly
  // upright right next to a dramatically tipped tub, which read as two
  // unrelated objects placed near each other rather than one cohesive
  // "tipped out of the cart" moment ("looks kinda sloppy thrown
  // together"). Capped well under the tub's own angle so it still
  // reads as the character tumbling, not just rotating like a box.
  const mineCartTipLean = (typeof mineCart !== "undefined" && mineCart.ending) ? mineCart.tipAngle * 0.4 : 0;
  const totalTilt = swayAngle + mineCartTipLean + (typeof forestGearRideAngle !== "undefined" ? forestGearRideAngle : 0);
  const swayCx = px + player.width / 2, swayCy = drawPy + player.height / 2;
  ctx.translate(swayCx, swayCy);
  ctx.rotate(totalTilt);
  ctx.translate(-swayCx, -swayCy);

  // body
  ctx.fillStyle = "#7a78b8";
  roundRect(ctx, px, drawPy, player.width, player.height, 8);
  ctx.fill();

  // outline body
  ctx.strokeStyle = "rgba(40,30,20,0.6)";
  ctx.lineWidth = 1.5;
  ctx.stroke();

  // eyes
  ctx.fillStyle = "#ffffff";
  ctx.beginPath();
  ctx.arc(px + 12, drawPy + 16, 3, 0, Math.PI*2);
  ctx.arc(px + 28, drawPy + 16, 3, 0, Math.PI*2);
  ctx.fill();

  ctx.fillStyle = "#2b2b2b";
  ctx.beginPath();
  ctx.arc(px + 12, drawPy + 17, 1.5, 0, Math.PI*2);
  ctx.arc(px + 28, drawPy + 17, 1.5, 0, Math.PI*2);
  ctx.fill();

  ctx.restore(); // closes the sway rotation
  ctx.restore(); // closes the clip
}

if (currentScene === "forest") {
  drawForestBrambleFrontLayer(camX); // cached -- covers Front's crossing strands AND the obstacle knots composited on top of them, same layering as before
} else if (currentScene === "molehole") {
  // foreground root pillars, drawn AFTER the player sprite so they sit
  // in front of it -- real depth instead of the player always being
  // the closest thing on screen
  drawMoleholeRootPillar(20, camX);
  drawMoleholeRootPillar(MOLEHOLE_WIDTH - 20, camX);
}


drawCrown(camX);
drawBoomerangPrompt(camX);
if (currentScene === "molehole") {
  // both the shaft's own activation pole AND the cushion-behind-pole
  // redraw below are drawn at a fixed WORLD x (MOLEHOLE_SHAFT_X) against
  // camX -- normal camera-follow doesn't run while riding the cart
  // (mineCart.active has its own separate scroll via mineCart.t, see
  // drawMineCartRide), so camX just sits frozen wherever it was the
  // instant the ride started. That left this pole drawn at a
  // near-constant screen position for the entire ride, reading as some
  // unrelated shaft that "travels with you the whole time" rather than
  // scrolling past like everything else. Simplest fix: this is the
  // shaft you just boarded FROM -- there's nothing for it to occlude
  // while actually riding, so just don't draw it during the ride at all.
  if (!mineCart.active) {
    drawMoleholeShaftActivation(camX);
    // the cushion-behind-pole occlusion (see the MOLEHOLE_CUSHIONS draw
    // loop above) only ever redrew the pole over the CUSHION -- the player
    // riding it still drew on top of everything, so the moment the
    // cushion swung behind the pole, the rider visibly floated in front of
    // it instead of also passing behind ("when player is on a moving
    // cushion... going behind the pole when cushion does?"). Redraw the
    // same pole segment again here, after the player sprite, for whichever
    // cushion the player is actually riding.
    if (moleholeShaftFixed && moleholeRidingCushion && moleholeCushionDepth(moleholeRidingCushion) < 0) {
      // stretched to cover the RIDER's full sprite (head to feet), not just
      // the cushion's own thin slice -- see this function's own comment
      drawMoleholeShaftPoleSegment(moleholeRidingCushion, camX, player.height + 4, 6);
    }
  }
  drawMineCartFrontRim();
  // was defined but never actually wired in anywhere -- the sink
  // phase's own darkening never played, which is a real chunk of why
  // the ending read as unfinished/sloppy ("emptying player from cart...
  // looks kinda sloppy thrown together"). Called here, after the player
  // sprite has already drawn (see this function's own comment), so the
  // player visibly sinks INTO the darkening vignette rather than the
  // darkness just painting over on top of them.
  drawMineCartEndingVignette();
}

// held item — floats above the head while selected, so it's clear it's
// "in play". Hidden during an active dig -- the digging flourish
// already shows the shovel being swung down at the hole, so keeping a
// second copy floating above the player's head at the same time just
// read as cluttered/confusing.
if (heldItem && !fallState.active && !activeDig) {
  const heldPos = getHeldItemWorldPos();
  if (heldItem === "honey") {
    drawHoneyPotShape(ctx, heldPos.x - camX, heldPos.y, 10, honeyScoops / 8);
  } else {
    drawCollectible(ctx, heldPos.x - camX, heldPos.y, 10, 0, heldItem);
  }
}

// carried book — same floating-above-head treatment as a held item,
// small closed-book icon matching each book's established color coding
if (carriedBook && !fallState.active) {
  const bookPos = getHeldItemWorldPos();
  const bx = bookPos.x - camX, by = bookPos.y;
  const isManual = carriedBook === "manual";
  const isMetaphors = carriedBook === "metaphors";
  if (isMetaphors) {
    ctx.fillStyle = "#1a1a1a";
    ctx.fillRect(bx - 6, by - 8, 12, 16);
    ctx.fillStyle = "#3f5766";
    ctx.fillRect(bx - 6, by - 8, 12, 5);
    ctx.strokeStyle = "#22303a";
    ctx.lineWidth = 1;
    ctx.strokeRect(bx - 6, by - 8, 12, 16);
  } else {
    ctx.fillStyle = isManual ? "#2f5a6a" : "#7a2f2f";
    ctx.fillRect(bx - 6, by - 8, 12, 16);
    ctx.strokeStyle = isManual ? "#1a3540" : "#5a2020";
    ctx.lineWidth = 1;
    ctx.strokeRect(bx - 6, by - 8, 12, 16);
  }
  if (isManual) {
    // small tooth icon, so the manual stands out at a glance even at
    // this tiny carried-icon size, not just a plain label stripe
    const tx = bx, ty = by - 4;
    ctx.fillStyle = "#f5f0e0";
    ctx.beginPath();
    ctx.moveTo(tx - 1.6, ty - 1);
    ctx.quadraticCurveTo(tx - 2, ty - 2.6, tx, ty - 2.6);
    ctx.quadraticCurveTo(tx + 2, ty - 2.6, tx + 1.6, ty - 1);
    ctx.quadraticCurveTo(tx + 1.8, ty, tx + 0.8, ty + 2);
    ctx.quadraticCurveTo(tx, ty + 2.6, tx - 0.8, ty + 2);
    ctx.quadraticCurveTo(tx - 1.8, ty, tx - 1.6, ty - 1);
    ctx.closePath();
    ctx.fill();
  } else if (!isMetaphors) {
    ctx.fillStyle = "#d4a520";
    ctx.fillRect(bx - 4, by - 5, 8, 1.5);
  }
}

drawSeasonTransition(ctx);
}
}
/* ======================================================
   MAIN LOOP
   ====================================================== */
function updateAutumnScene(deltaTime) {
updateLeafTrees(deltaTime);
updateSeesaw(deltaTime);
updateWoodpecker(deltaTime);
updateSeesawProjectile();
updateVines(deltaTime);
updateAcorns();
updateVinePumpkin();
updateWormRock();

// honey falling from the hive, once knocked
if (honey.falling) {
  honey.heightAboveGround -= HONEY_FALL_SPEED * deltaTime;
  if (honey.heightAboveGround <= 15) {
    honey.heightAboveGround = 15;
    honey.falling = false; // settled — now pickupable
  }
}

// APPLE DROP LOGIC
// ================== APPLE STATE MACHINE ==================

const dt = deltaTime;

// --- geometry ---
const appleBottom = apple.y + apple.r;
const appleCenterX = apple.x;

const overStump =
  stump &&
  appleCenterX > stump.x &&
  appleCenterX < stump.x + stump.width;

const landingY = overStump ? gy - stump.height : gy;

// --- support check ---
const supported = appleBottom >= landingY && apple.vy >= 0;

// The apple comes to rest through the LAND step below, which also
// kicks off the bounce. (The old hard-lock here pre-empted that and
// stopped the apple from ever bouncing.)

// --- falling permission ---
if (!supported && apple.canFall(performance.now())) {
  apple.falling = true;
}

// --- falling physics ---
if (apple.falling) {
  apple.vy += apple.gravity * dt;

  if (apple.vy > apple.terminalVelocity) {
    apple.vy = apple.terminalVelocity;
  }

  apple.vy *= apple.airDrag;
  apple.y += apple.vy * dt;
}


// console.log(
//   "STATE",
//   "falling:", apple.falling,
//   "vy:", apple.vy,
//   "landed:", apple.landed,
//   "bottom>=ground:", appleBottom >= landingY
// );  


// LAND 

if (
  apple.falling &&
  apple.vy > 0 &&
  !apple.landed &&
  appleBottom >= landingY
  
) {
  const impactVy = apple.vy;   // how fast it was actually falling on impact

  apple.y = landingY - apple.r;
  apple.vy = 0;
  apple.falling = false;
  apple.landed = true;

  apple.bounce = 0;
  apple.bounceVy = impactVy * apple.bounceRestitution;   // first hop derived from real fall speed
  apple.settleThreshold =
    impactVy * Math.pow(apple.bounceRestitution, apple.targetBounces); // velocity floor for ~4 hops
  apple.glitter = 90;
}
  
// bounce + crack
if (apple.landed && !apple.settled) {
  
  apple.bounceVy -= apple.gravity * dt;   // same gravity the apple fell under
  apple.bounce += apple.bounceVy * dt;    // hop height above the rest surface

  if (apple.bounce <= 0) {          // came back down to the surface
    apple.bounce = 0;
    apple.bounceVy = -apple.bounceVy * apple.bounceRestitution;   // rebound, losing energy

    if (Math.abs(apple.bounceVy) < apple.settleThreshold) {   // hop too weak now — settle and split
      apple.bounceVy = 0;
      apple.settled = true;
      apple.landed = false;

      if (!apple.cracked) {
        apple.cracked = true;
        apple.split = true;
        apple.splitTimer = 90;
      }
    }
  }
} 
// --- CREATE 3 APPLE PIECES ---
// ================== APPLE SPLIT SPAWN ==================
if (apple.split) {

  const appleCenterX = apple.x;
  const appleCenterY = apple.y;

  const spread = Math.PI / 3;      // total 60° fan
  const baseAngle = -Math.PI / 2;  // upward

  for (let i = 0; i < 3; i++) {
    const angle = baseAngle + spread * (i - 1);
    const speed = 180 + Math.random() * 40;

    applePieces.push(
      createApplePiece(appleCenterX, appleCenterY, angle, speed));
  }

  apple.split = false; // 🔒 one-time spawn
  apple.pickupReady = true;
}

//       // apple can now be collected
//     apple.pickupReady = true;
//     }
//   }
// }
    

  

  // UPDATE APPLE PIECES (E1 GOES HERE)
  applePieces.forEach(p => {
    if (p.settled || p.collected) return;

    p.vy += p.gravity * deltaTime;
    p.vx *= p.airDrag;
    p.vy *= p.airDrag;

    p.x += p.vx * deltaTime;
    p.y += p.vy * deltaTime;
    p.rotation += p.spin * deltaTime;

    if (p.y + p.r >= gy) {
      p.y = gy - p.r;
      p.vx *= 0.4;
      p.vy = 0;
      p.spin *= 0.3;
      p.settled = true;
    }
  });

  // PICKUP: press down near a settled apple piece (checked before frog interaction)
  let pickupHandledThisFrame = false;

  applePieces.forEach(p => {
    if (!p.settled || p.collected || p.collecting) return;

    const pieceHeight = gy - p.y; // piece coords are world-space; convert to height-above-ground

    if (pressedDownNear(p.x, pieceHeight, 26, 10, 10)) {
      p.collecting = true; // stops it being drawn/re-triggered as a ground piece
      startCollectAnimation(p, "appleSlice");
      pickupHandledThisFrame = true;
    }
  });

  // boomerang: elevated, requires catching it on the way down from a jump —
  // same "must be descending" logic platform-landing already uses, generous
  // vertical tolerance so most of the descent counts, not a single frame
  if (!boomerang.collected && !boomerang.collecting && !pickupHandledThisFrame) {
    if (player.vy <= 0 && pressedDownNear(boomerang.x, boomerang.heightAboveGround, 26, 20, 20)) {
      boomerang.collecting = true;
      startCollectAnimation(
        { x: boomerang.x, y: gy - boomerang.heightAboveGround, size: 10, rotation: 0 },
        "boomerang"
      );
      pickupHandledThisFrame = true;
    }
  }

  // honey: only pickable once the hive's actually been knocked down AND it's settled
  if (honey.available && !honey.collected && !honey.collecting && !honey.falling && !pickupHandledThisFrame) {
    if (pressedDownNear(honey.x, honey.heightAboveGround, 26, 20, 20)) {
      honey.collecting = true;
      startCollectAnimation(
        { x: honey.x, y: gy - honey.heightAboveGround, size: 10, rotation: 0 },
        "honey"
      );
      pickupHandledThisFrame = true;
    }
  }


  // apple glitter decay
if (apple.glitter > 0) apple.glitter--;
if (apple.splitTimer > 0) apple.splitTimer--;

  // --- FROG INTERACTION (per-frame, correct place) ---
  const frogCenterX = frog.x + frog.width / 2;

  if (pressedDownNear(frogCenterX, 0, 70, 6, 999) && !frog.active && !pickupHandledThisFrame) {
    frog.active = true;
    frog.tip = 30;
  }

  // --- CROW INTERACTION -- only once the hay bales have toppled,
  // since the crow's own area isn't reachable before then ---
  if (hayBales.toppled) {
    updateNPCIdle(crow);
    const crowCenterX = crow.x + crow.width / 2;
    if (pressedDownNear(crowCenterX, crow.y, 130, 45, 999) && !crow.active && !pickupHandledThisFrame) {
      crow.active = true;
      crow.tip = 30;
    } else if (crow.active && keys.spaceJustPressed && isPlayerNear(crowCenterX, crow.y, 130, 45, 999) &&
               heldItem === "pumpkin" && inventory.pumpkin > 0 && !crow.offeredPumpkin) {
      // pumpkin isn't deducted here -- the player still carries it and
      // needs to walk it over and place it themselves at the station
      crow.offeredPumpkin = true;
      crow.facing = 1; // flips to face right, toward the station
    }
  }

  // --- CARVING STATION PLACEMENT -- space near the station's own
  // platform, with the pumpkin specifically in hand, places it down
  // on the cloth ---
  if (!carvingStation.pumpkinPlaced && !carvingStation.active && heldItem === "pumpkin" && inventory.pumpkin > 0 &&
      keys.spaceJustPressed && isPlayerNear(carvingStation.x, carvingStation.platformHeight, 40, 20, 999)) {
    inventory.pumpkin -= 1;
    if (inventory.pumpkin <= 0) { delete inventory.pumpkin; heldItem = null; }
    updateInventoryUI();
    carvingStation.pumpkinPlaced = true;
    carvingStation.placingT = 0;
  }

  // the finished pumpkin now stays permanently at the station once
  // grown -- no pickup, no inventory item. It's a fixture, not
  // something carried away.

if (apple.landed && !frogNoticedApple) {
  frogNoticedApple = true;
  frog.tip = 40;
}

if (frog.active && apple.cracked && inventory.appleSlice > 0 && orchardChoice === null && keys.space) {
  orchardPaths.forEach(p => {
    if (isPlayerNear(p.x, 0, 40, 0, 0)) {
      orchardChoice = p.id;
      frog.tip = 40;
    }
  });
}

}

// PLACEMENT SLOTS and the autumn-side doorway check -- extracted out
// of updateAutumnScene since these are scene-independent concepts
// (holding an item, walking up to any slot or door, wherever the
// player currently is). Previously nested inside updateAutumnScene,
// which meant any placement slot meant to be used from a different
// scene (like the new forest door's slot, used from spring) would
// never actually be checked.
function updateGenericPlacementAndDoors() {
  // PLACEMENT SLOTS: place the currently held item into a matching slot
  placementSlots.forEach(slot => {
    if (slot.filled) return;

    if (
      heldItem === slot.acceptsItemType &&
      inventory[heldItem] > 0 &&
      pressedDownNear(slot.x, slot.heightAboveGround, 30, 10, 10)
    ) {
      const itemToPlace = heldItem;

      inventory[itemToPlace]--;
      if (inventory[itemToPlace] <= 0) delete inventory[itemToPlace];
      heldItem = null;
      updateInventoryUI();

      startPlaceAnimation(itemToPlace, slot.x, gy - slot.heightAboveGround, () => {
        slot.filled = true;
        slot.onFill(itemToPlace);
      });
    }
  });

  // DOORWAY: only enterable once the connection is unlocked
  if (
    connections[0].filled &&
    seasonTransition.phase === "idle" &&
    pressedDownNear(
      connections[0].doors.autumn.x + connections[0].doors.autumn.width / 2,
      0, 30, 6, 6
    )
  ) {
    startSeasonTransition("spring");
  }
}

// shared — the brief "settled on the cloud" beat, then the real transition fires
function updateCloudLanding(deltaTime) {
  if (!cloudLanding.active) return;

  cloudLanding.t += deltaTime * 1000;

  if (cloudLanding.t >= CLOUD_LANDING_HOLD) {
    cloudLanding.active = false;
    cloudLanding.t = 0;
    startSeasonTransition("clouds");
  }
}

// shared — runs regardless of which scene initiated the fall, so a fall
// started in the clouds (via cloudHole) completes correctly even though
// updateCloudsScene, not updateSpringScene, is what's running that frame
function updateFallState(deltaTime) {
  if (!fallState.active) return;

  fallState.t += deltaTime * 1000;

  if (fallState.t >= fallDurationForMode(fallState.mode)) {
    fallState.active = false;
    fallState.t = 0;

    if (fallState.mode === "tunnelHole") {
      // the mole hole's own deeper hole down into tunnel town -- unlike
      // the other modes, this doesn't relocate the player itself (the
      // existing fade transition handles that scene swap); it just
      // hands off to it once the sink animation has actually finished
      // playing, instead of the two running as two entirely separate,
      // uncoordinated systems
      fallJustEndedIntoTransition = true;
      startSeasonTransition("tunneltown");
    } else if (fallState.mode === "cloudHole") {
      // switch scenes and arrive mid-air — floating down out of the clouds,
      // not teleported straight to the ground
      currentScene = "spring";
      discoveredScenes.spring = true;
      updateMapUI();
      hasReturnedFromClouds = true; // the willow's real unlock condition

      // close to, visually under the goal cloud — the immunity window
      // below (not distance) is what actually prevents an instant retrigger
      player.x = goalCloud.x + 5;
      player.y = 200;
      player.vy = 0;
      player.vx = 0;
      player.jumping = true;
      player.launched = true;       // reuses the same floaty-descent physics as a failed swing launch
      player.launchGravityMult = 1; // reset, same reasoning as the swing-release site above
      player.launchPeakHeight = player.y;
      player.cloudLandingImmunity = 1500; // ms grace period before the goal-cloud hit check can fire again
      cameraX = Math.max(0, player.x - canvas.width * 0.4);
    } else {
      // faze back to the start of the spring zone
      player.x = sceneSpawns.spring.x;
      player.y = 0;
      player.vy = 0;
      player.jumping = false;
      player.usedDoubleJump = false;
      cameraX = 0;
    }
  }
}

function updateSpringScene(deltaTime) {

  // mid-fall — timer/completion handled globally now, just don't run
  // anything else in this scene while it's happening
  if (fallState.active) {
    return;
  }

  // RABBIT INTERACTION — same shape as frog's trigger
  const rabbitCenterX = rabbit.x + rabbit.width / 2;
  if (pressedDownNear(rabbitCenterX, 0, 70, 6, 999) && !rabbit.active) {
    rabbit.active = true;
    rabbit.tip = 30;
  }
  updateNPCIdle(rabbit);
  updateRabbitWander(deltaTime);

  // mounting the swing now happens via jump, in handleInput — just run its physics here
  updateSwing(deltaTime);

  updateWiggleBush(deltaTime);
  updateWillow(deltaTime);
  updateDigPlantVine(deltaTime);
  updateSquirrelWander(deltaTime);
  updateTreeSticks(deltaTime);
  updateSnailWander(deltaTime);
  updateGraftTrees(deltaTime);
  updateKnockableFruits(deltaTime);
  updateNPCIdle(squirrel);

  // HOLES — only trip the fall if grounded (player.y<=0) and NOT mid-jump
  // over it; jumping keeps player.y > 0 while crossing the hole's x-range
  if (player.y <= 0) {
    const playerCenterX = player.x + player.width / 2;
    const matchedHole = springHoles.find(h => playerCenterX > h.x && playerCenterX < h.x + h.width);

    if (matchedHole) {
      player.x = matchedHole.x + matchedHole.width / 2 - player.width / 2;
      fallState.active = true;
      fallState.t = 0;
      fallState.mode = "hole";
    }
  }

  // TULIP PICKUP — same shape as boomerang's pickup in autumn
  if (!tulip.collected && !tulip.collecting) {
    if (pressedDownNear(tulip.x, tulip.heightAboveGround, 26, 10, 10)) {
      tulip.collecting = true;
      startCollectAnimation(
        { x: tulip.x, y: gy - tulip.heightAboveGround, size: 10, rotation: 0 },
        "tulip"
      );
    }
  }

  // walk through the same connection, back to autumn — same door,
  // same unlock state, just approached from the other side
  if (
    connections[0].filled &&
    seasonTransition.phase === "idle" &&
    pressedDownNear(
      connections[0].doors.spring.x + connections[0].doors.spring.width / 2,
      0, 30, 6, 6
    )
  ) {
    startSeasonTransition("autumn");
  }

  // forward through the new door into forest
  if (
    connections[1].filled &&
    seasonTransition.phase === "idle" &&
    pressedDownNear(
      connections[1].doors.spring.x + connections[1].doors.spring.width / 2,
      0, 30, 6, 6
    )
  ) {
    startSeasonTransition("forest");
  }
}

function update(){

  // console.log("UPDATE START y =", apple.y);

const now = performance.now();
const deltaTime = Math.min((now - lastTime) / 1000, 0.05);
lastTime = now;

  if (bookReader.active || bookReader.opening || bookReader.closing) {
    updateBookReader(deltaTime);
    keys.upJustPressed = false;
    keys.leftJustPressed = false;
    keys.rightJustPressed = false;
    keys.spaceJustPressed = false;
    requestAnimationFrame(update);
    draw();
    return;
  }

  if (corkboardReader.active || corkboardReader.opening || corkboardReader.closing) {
    updateCorkboardReader(deltaTime);
    keys.upJustPressed = false;
    keys.leftJustPressed = false;
    keys.rightJustPressed = false;
    keys.spaceJustPressed = false;
    requestAnimationFrame(update);
    draw();
    return;
  }

  if (carvingUI.active || carvingUI.opening || carvingUI.closing) {
    updateCarvingUI(deltaTime);
    keys.upJustPressed = false;
    keys.leftJustPressed = false;
    keys.rightJustPressed = false;
    keys.spaceJustPressed = false;
    requestAnimationFrame(update);
    draw();
    return;
  }

  handleInput();
  applyPhysics();

  if (currentScene === "autumn") {
    updateHayBales(deltaTime);
    updateTreeCrow(deltaTime);
    updateSmallCrows(deltaTime);
    if (hayBales.toppled) updateBat(deltaTime);
    updateCarvingStation(deltaTime);
    if (!hayBales.toppled) {
      // standing wall -- blocks passage entirely until toppled
      if (player.x + player.width > hayBales.x - 20 && player.x < hayBales.x + 20) {
        if (player.x < hayBales.x) player.x = hayBales.x - 20 - player.width;
        else player.x = hayBales.x + 20;
      }
    } else {
      // toppled -- each bale is now individually jumpable, matching
      // its own actual scattered position and height rather than one
      // flat zone across the whole pile. Finds the single best
      // (highest) matching bale first, since overlapping bales could
      // otherwise have a later one in the array incorrectly override
      // a more correct landing
      const toppledPositions = getHayBaleToppledPositions();
      const BALE_HALF_WIDTH = 15, BALE_HALF_HEIGHT = 13;
      let bestBaleTop = null;
      toppledPositions.forEach(p => {
        const baleX = hayBales.x + p.dx;
        const baleTop = -p.dy + BALE_HALF_HEIGHT;
        if (
          player.x + player.width > baleX - BALE_HALF_WIDTH &&
          player.x < baleX + BALE_HALF_WIDTH &&
          player.y <= baleTop &&
          player.y >= baleTop - 30 &&
          player.vy <= 0
        ) {
          if (bestBaleTop === null || baleTop > bestBaleTop) bestBaleTop = baleTop;
        }
      });
      if (bestBaleTop !== null) {
        player.y = bestBaleTop;
        player.vy = 0;
        player.jumping = false;
        player.usedDoubleJump = false;
      }

      // the carving station's own small platform -- separate from the
      // main pile, only reachable once that pile itself has toppled
      const stationTop = carvingStation.platformHeight;
      if (
        player.x + player.width > carvingStation.x - 30 &&
        player.x < carvingStation.x + 30 &&
        player.y <= stationTop &&
        player.y >= stationTop - 30 &&
        player.vy <= 0
      ) {
        player.y = stationTop;
        player.vy = 0;
        player.jumping = false;
        player.usedDoubleJump = false;
      }

      // decorative hay piles -- all genuinely jumpable now, same
      // landing pattern as every other platform in this area
      decorativeHayPiles.forEach(pile => {
        if (
          player.x + player.width > pile.x - 24 &&
          player.x < pile.x + 24 &&
          player.y <= pile.topHeight &&
          player.y >= pile.topHeight - 30 &&
          player.vy <= 0
        ) {
          player.y = pile.topHeight;
          player.vy = 0;
          player.jumping = false;
          player.usedDoubleJump = false;
        }
      });
    }
  }



updateFallState(deltaTime); // shared — runs before scene dispatch, regardless of which scene started the fall
updateCloudLanding(deltaTime);
updateCrown(deltaTime); // scene-independent — C should work anywhere, not just autumn
if (inventory.boomerang > 0 && !boomerangPromptState.promptEverShown && boomerangPromptState.promptAnimT < CROWN_PROMPT_MATERIALIZE_DURATION) {
  boomerangPromptState.promptAnimT += deltaTime * 1000;
}
updateLampLighting(); // scene-independent check inside, so it correctly turns off if the scene changes mid-hold
updateGenericPlacementAndDoors(); // placement slots and the autumn-side doorway -- runs regardless of current scene

if (currentScene === "autumn") {
  updateAutumnScene(deltaTime);
} else if (currentScene === "spring") {
  updateSpringScene(deltaTime);
} else if (currentScene === "forest") {
  updateForestScene(deltaTime);
} else if (currentScene === "clouds") {
  updateCloudsScene(deltaTime);
} else if (currentScene === "oak") {
  updateOakScene(deltaTime);
} else if (currentScene === "ratroom") {
  updateRatRoomScene(deltaTime);
} else if (currentScene === "molehole") {
  updateMoleholeScene(deltaTime);
} else if (currentScene === "tunneltown") {
  updateTunnelTownScene(deltaTime);
}

  // throw the boomerang — spacebar while it's held, works in any scene.
  // !boomerangThrow guards against re-triggering while holding the key down.
  if (keys.space && heldItem === "boomerang" && !boomerangThrow) {
    throwBoomerang();
  }
  updateBoomerangThrow(deltaTime);

  if (player.cloudLandingImmunity > 0) player.cloudLandingImmunity -= deltaTime * 1000;

  updateFlyingItems(deltaTime, cameraX); // shared system, runs in any scene

updateSeasonTransition(deltaTime);

  draw();

  const targetCam = player.x - canvas.width*0.4;
  if (hayBales.waiting) {
    // tight during the pause -- just a sliver of space to the right,
    // the tower dominates the frame before anything happens
    cameraX = hayBales.x - (canvas.width - 40);
  } else if (hayBales.toppling) {
    // eases open as the fall actually progresses, revealing more
    // space to the right the further along the topple gets
    const p = Math.min(1, hayBales.toppleT / HAY_BALE_TOPPLE_MS);
    const margin = 40 + p * 260;
    cameraX = hayBales.x - (canvas.width - margin);
  } else {
    cameraX += (targetCam - cameraX)*0.08;
    if (Math.abs(targetCam - cameraX) < 0.1) cameraX = targetCam; // snaps once negligibly close -- the easing formula alone never mathematically settles, causing a perpetual sub-pixel drift in everything drawn relative to the camera
  }
  if (cameraX<0) cameraX=0;
  // ratroom's own right-side camera clamp, mirroring the left-side
  // pattern -- caps the camera a bit past where the hay ground cover
  // actually ends, so the camera stops there even if the player keeps
  // walking on toward their own boundary further out
  if (currentScene === "ratroom" && cameraX > 625) cameraX = 625;
  // molehole's own right-side camera clamp, same small-room pattern
  if (currentScene === "molehole" && cameraX > MOLEHOLE_WIDTH - canvas.width + 40) cameraX = Math.max(0, MOLEHOLE_WIDTH - canvas.width + 40);
  if (currentScene === "tunneltown" && cameraX > TUNNELTOWN_WIDTH - canvas.width + 40) cameraX = Math.max(0, TUNNELTOWN_WIDTH - canvas.width + 40);
  // oak's left side has its own tall bookshelf (x:192) that should be
  // visible/reachable from directly left of the entrance door (x:294) --
  // clamped a little past the shelf's own left edge (~157) so there's a
  // touch of breathing room, but not so much empty wall shows past it
  if (currentScene === "oak" && cameraX < 130) cameraX = 130;

  keys.leftJustPressed = false;
  keys.rightJustPressed = false;
  keys.upJustPressed = false;
  keys.spaceJustPressed = false;
  keys.cJustPressed = false;

  // console.log("UPDATE END y =", apple.y);
  
  requestAnimationFrame(update);
}


